// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Antik ve Doğu edebiyatları: Homeros, Şehname, Hint ve Çin klasikleri (orta).
const ozLiterature12Orta = <(String, String, List<String>, String)>[
  ('Apollon\'un Akha ordusuna salgın hastalık göndermesinin İlyada\'daki nedeni nedir?', 'Rahibi Khryses\'in kızının Agamemnon tarafından geri verilmemesi', ['Akhilleus\'un bir tapınağı yıkması', 'Odysseus\'un kutsal bir geyiği öldürmesi', 'Paris\'in Apollon\'a adak adayıp yerine getirmemesi ve rahibi aşağılaması'], 'Apollon rahibi Khryses kızı Khryseis\'i geri istemiş, Agamemnon reddedince tanrı orduya ok yağdırarak salgın salmıştır.'),
  ('Patroklos savaşa Akhilleus\'un zırhıyla girdiğinde Truvalılar üzerinde nasıl bir etki bekleniyordu?', 'Onu Akhilleus sanıp korkacaklardı', ['Zırhın tanrısal gücüyle yenilmez olacaktı', 'Zırh Hektor\'u kör edecekti', 'Zırh Akhaları görünmez kılacaktı'], 'Akhilleus arkadaşının kendi zırhını giymesine izin vererek Truvalıların moralini bozmayı amaçladı; plan kısmen işe yaradı ama Patroklos sonunda öldürüldü.'),
  ('Akhilleus\'un kalkanının uzun betimlendiği bölüm, sanat yapıtının sözle ayrıntılı tarif edilmesi anlamında hangi terime örnek gösterilir?', 'Ekphrasis', ['Peripeteia', 'Prolog', 'Antistrofe'], 'Bir sanat nesnesinin edebî metinde ayrıntılı betimlenmesine ekphrasis denir; Akhilleus\'un kalkanı bunun en eski örneklerindendir.'),
  ('Hektor\'un oğlunun, babasının miğferinin tüylerinden korkup ağladığı sahne İlyada\'nın hangi yönünü gösterir?', 'Savaşçı kahramanın aynı zamanda aile babası olan insani yüzünü', ['Truvalıların tanrılara inançsızlığını ve savaştan bıkkınlığını gösterir', 'Hektor\'un savaşa isteksizliğini', 'Akhaların üstünlüğünü'], 'Hektor ile Andromakhe\'nin vedalaşma sahnesi, kahramanlık ile aile sevgisi arasındaki gerilimi gösterir.'),
  ('İlyada\'da hangi iki kahraman, babalarının konukseverlik bağını hatırlayıp savaş alanında zırh değiştirir?', 'Glaukos ile Diomedes', ['Hektor ile Aias', 'Paris ile Menelaos', 'Odysseus ile Sarpedon'], 'Karşı karşıya gelen iki savaşçı atalarının dostluğunu fark edip birbirine zarar vermeden zırh takas eder; bu sahne ksenia geleneğinin önemini gösterir.'),
  ('Akha ordusunun en çirkin ve ağzı bozuk askeri olarak betimlenen, Odysseus\'tan dayak yiyen kişi kimdir?', 'Thersites', ['Dolon', 'Pandaros', 'Phoinix'], 'Thersites, Agamemnon\'u küfürle eleştirince Odysseus tarafından asasıyla dövülür.'),
  ('Zeus\'un oğlu olup Lykia komutanı sıfatıyla Truva yanında savaşan ve Patroklos tarafından öldürülen kahraman kimdir?', 'Sarpedon', ['Glaukos', 'Aineias', 'Rhesos'], 'Sarpedon\'un cesedi Hypnos ile Thanatos tarafından Lykia\'ya götürülür.'),
  ('Odysseus\'un adamlarının Güneş tanrısı Helios\'un kutsal sığırlarını kesmesi hangi sonuca yol açar?', 'Zeus yıldırımla gemiyi batırır, Odysseus dışında herkes ölür', ['Odysseus İthaka\'ya hemen ulaşır', 'Poseidon adamları taşa çevirir', 'Athena adamları yeniden diriltir'], 'Tanrıların cezası olarak gemi parçalanır; yalnızca Odysseus hayatta kalır ve Kalypso\'nun adasına sürüklenir.'),
  ('Phaiak sarayında Odysseus\'un Truva öyküsünü duyup gözyaşı döktüğü sırada şarkı söyleyen kör ozan kimdir?', 'Demodokos', ['Phemios', 'Teiresias', 'Linos'], 'Demodokos, Homeros\'un kendi kimliğiyle ilişkilendirilen kör ozan figürüdür; ozanın toplumdaki saygın yerini gösterir.'),
  ('Penelope\'nin taliplere önerdiği yarışmada Odysseus\'un yayı ile hangi hedef vurulmalıdır?', 'On iki baltanın halkalarından geçen ok', ['Duvardaki bir kalkan', 'Uçan bir güvercin', 'Salonun ortasındaki bir elmanın tam ortası'], 'Yayı yalnız Odysseus gerebilir ve oku sıralı baltaların halkalarından geçirir; ardından talipleri öldürmeye başlar.'),
  ('Penelope, kendisine gelen yabancının gerçekten Odysseus olup olmadığını hangi sınavla anlar?', 'Zeytin ağacından yapılmış yatağın yerinin değiştirilemeyeceğini sormasıyla', ['Odysseus\'un yayını germesiyle', 'Telemakhos\'un onaylamasıyla', 'Bir kehanetin yorumuyla'], 'Yatağı yalnız ikisinin bildiği gizli yapıda olduğundan, Odysseus\'un bu ayrıntıyı bilmesi onun kimliğinin kesin kanıtı olur.'),
  ('Aiolos\'un Odysseus\'a verdiği torbada ne vardı ve neden felaket doğurdu?', 'Rüzgârlar; adamlar altın sanıp açınca gemi fırtınayla geri sürüklendi', ['Gümüş; adamlar paylaşmak için kavga etti', 'Su; gemi susuz kaldı', 'Silah; adamlar isyan etti'], 'Adamlar torbada hazine olduğunu sanıp açınca rüzgârlar kaçar; gemi İthaka\'nın görüldüğü noktadan geri sürüklenir.'),
  ('Odysseia\'da Odysseus\'un yolculuk maceralarının kronolojik sıra yerine, sonradan hatırlanarak anlatılması hangi anlatı tekniğidir?', 'Geriye dönüş', ['Mektup biçimi', 'Gerçek zamanlı tek anlatım', 'Rüya içinde anlatım'], 'Odysseus, Truva sonrası yolculuğunu Alkinoos\'un sarayında birinci kişi ağzından anlatır; olay örgüsü kronolojik sıradan ayrılır.'),
  ('Homeros destanlarında \'in medias res\' tekniği ne demektir?', 'Hikâyeye olayın ortasından başlayıp önceki olayları sonradan anlatma', ['Hikâyeyi tanrılara seslenerek bitirme', 'Her bölümü bir benzetmeyle açma', 'Hikâyeyi baştan sona kronolojik anlatma'], 'İlyada savaşın onuncu yılında, Odysseia ise Odysseus\'un dönüş yolculuğunun sonlarında başlar; geçmiş olaylar sonradan aktarılır.'),
  ('Milman Parry\'nin Homeros araştırmalarındaki temel savı hangisidir?', 'Destanlar, ezberlenmiş formül ve kalıplarla sözlü olarak oluşturulmuştur', ['Destanlar tek bir yazarın yazılı taslaklarından çıkmıştır', 'Destanlar Roma döneminde yazılmıştır', 'Destanlar yalnız çeviri metinlerdir'], 'Parry ve öğrencisi Albert Lord, Yugoslav ozanlarını inceleyerek formüllerin sözlü şiirde hızlı besteleme işlevi gördüğünü savundu.'),
  ('İlyada ve Odysseia\'nın bölümlere ayrılışı hakkında hangisi doğrudur?', 'Her biri 24 bölümdür ve bölümler Yunan harfleriyle gösterilir', ['İlyada 12, Odysseia 24 bölümdür', 'Her biri 7 bölümdür', 'Her biri 100 bölümdür'], 'Bölümlere ayrılış İskenderiye bilginlerine atfedilir; her destan Yunan alfabesinin 24 harfiyle numaralanır.'),
  ('Homeros\'un destanlarına Mousa\'ya seslenerek başlaması neyi yansıtır?', 'Şiirsel bilginin tanrısal ilhamdan geldiği inancını', ['Ozanın yazıya geçişini', 'Tanrılara karşı eleştirel tavrını', 'Destanın tarihsel bir belge olduğu iddiasını ve ozanın tanık olduğunu'], 'Antik düşüncede ozan yalnız Mousaların bilgisini aktarır; bu yüzden eserin başında ilham dilenir.'),
  ('Truva Savaşı\'nın nedenlerini ve öncesini anlatan, kaybolmuş epik şiir hangisidir?', 'Kypria', ['Telegonia', 'Aithiopis', 'Nostoi'], 'Kypria, Epik Devir\'in İlyada\'dan önceki olayları içeren şiiridir; yalnız parçalar ve özetler günümüze ulaşmıştır.'),
  ('Truva Savaşı sonrası Akha kahramanlarının eve dönüşlerini konu alan kayıp epik şiirin adı nedir?', 'Nostoi', ['Kypria', 'Aithiopis', 'Thebais'], 'Nostoi \'dönüşler\' demektir; Odysseia\'dan başka kahramanların dönüş öykülerini içerirdi ve nostalji sözcüğü bu kökle ilgilidir.'),
  ('Homeros\'un doğum yeri konusunda antik kaynaklarda en çok adı geçen Ege adası hangisidir?', 'Khios', ['Girit', 'Naksos', 'Rodos'], 'Birçok kent Homeros\'u kendine mal etmiştir; Khios ve İzmir (Smyrna) en güçlü adaylar olarak anılır.'),
  ('Homeros\'un destanlarındaki tanrı tasviri Yunan dininin hangi özelliğine işaret eder?', 'Tanrıların insan biçimli ve insan duygularına sahip olması', ['Tek tanrılı bir inanç', 'Tanrıların soyutluğu', 'Tanrıların insanlardan uzak, sessiz ve hiçbir duygu taşımayan varlıklar olması'], 'Homerik tanrılar kıskanç, öfkeli, aşık varlıklardır; bu anlayışa antropomorfizm denir.'),
  ('Odysseus\'un ölüler diyarına inişini anlatan Odysseia bölümü hangi adla anılır?', 'Nekyia', ['Telemakheia', 'Mnesterophonia', 'Doloneia'], 'Nekyia \'ölülere danışma\' demektir; sonraki edebiyatta (Aeneis, İlahi Komedya) benzer yeraltı yolculuklarına öncülük etmiştir.'),
  ('Hesiodos, \'Eserler ve Günler\'de insanlık tarihini hangi biçimde sınıflandırır?', 'Beş çağ: altın, gümüş, tunç, kahramanlar ve demir', ['Üç çağ: taş, tunç, demir', 'Dört çağ: ateş, su, toprak ve hava, her biri bin yıllık', 'Yedi çağ: tanrıların günleri'], 'Ahlaki gerilemeyi anlatan çağlar öyküsü, demir çağını Hesiodos\'un yaşadığı kötü dönem olarak gösterir.'),
  ('Hesiodos\'un Theogonia\'sında Mousalar nerede ve nasıl görünür?', 'Helikon Dağı\'nda ozana şiir armağan eder', ['Olympos\'ta Zeus\'u eğlendirir', 'Delphoi\'da kehanet verir', 'Athena\'nın tapınağında Mousalarla birlikte şarkı söyler'], 'Hesiodos, Helikon yamaçlarında koyun güderken Mousaların kendisini ozan yaptığını anlatır.'),
  ('Homeros ve Hesiodos arasındaki üslup farkı için hangisi doğrudur?', 'Homeros kahramanlık öyküsü anlatır, Hesiodos öğretici ve ahlaki içerik işler', ['Homeros öğretici, Hesiodos tiyatro yazarıdır', 'İkisi de kahramanlık destanı yazmıştır', 'Homeros düzyazı, Hesiodos şiir kullanmıştır'], 'Hesiodos\'un şiiri öğretici (didaktik) epiğe örnek olup çiftçilik, adalet ve tanrı soyağacı gibi konuları işler.'),
  ('Savaşta kalkanını bırakıp kaçtığını şiirinde alaylı bir sesle anlatan ve jambik şiirin ustası sayılan arkaik Yunan şairi kimdir?', 'Arkhilokhos', ['Tyrtaios', 'Alkman', 'Mimnermos'], 'Arkhilokhos, kahramanlık ideallerine karşı kişisel ve alaycı bir tutum sergileyen ilk Yunan şairlerindendir.'),
  ('Spartalıları savaşa hazırlayan, kahramanca ölümü öven elegeialarıyla bilinen şair kimdir?', 'Tyrtaios', ['Solon', 'Simonides', 'Theognis'], 'Tyrtaios\'un savaş şiirleri vatan uğruna ölmeyi yüceltir ve Sparta\'nın askerî ahlakını biçimlendirmiştir.'),
  ('Mytilene\'li olup siyasal çekişmeleri ve \'devlet gemisi\' alegorisini işlemesiyle bilinen şair kimdir?', 'Alkaios', ['Alkman', 'Anakreon', 'Hipponaks'], 'Alkaios, Lesbos\'ta Sappho ile aynı dönemde yaşamış, siyasal sürgünlük yaşamış ve kendi adını taşıyan kıta biçimini kullanmıştır.'),
  ('Esas olarak Sparta için kız korolarına şarkılar (partheneia) yazan arkaik şair kimdir?', 'Alkman', ['Stesikhoros', 'Ibykos', 'Bakkhylides'], 'Alkman\'ın partheneion\'u koro lirizminin en eski örneklerindendir ve Sparta ibadet törenleriyle ilişkilidir.'),
  ('Yunan lirik şiirinde \'skolion\' ne anlama gelir?', 'Şölen ve içki sofralarında söylenen şarkı', ['Düğün koşuğu', 'Zafer kazanan atletlere söylenen koşuk', 'Cenaze ağıtı'], 'Skolion, ziyafet toplantılarında sırayla söylenen kısa şarkıdır; bazı örnekleri günümüze ulaşmıştır.'),
  ('Theokritos\'un çoban şiirlerinde ortaya çıkan \'idyll\' sözcüğü sonraki edebiyatta nasıl bir anlam kazanmıştır?', 'Kırsal, huzurlu ve sevimli bir yaşam tasviri', ['Savaşı öven ve kahramanları yücelten uzun destan', 'Ölüm üzerine ağıt', 'Hiciv şiiri'], 'Theokritos\'un \'eidyllia\' adlı kısa şiirleri, sonraki Latin pastoral şiirini (Vergilius\'un Eclogae\'si) etkilemiştir.'),
  ('Lirik şiir ile epik şiiri karşılaştıran aşağıdaki yargılardan hangisi doğrudur?', 'Lirik şiir kişisel duygu ve görüşü, epik şiir kahramanlık öyküsünü ağırlıklı işler', ['Lirik şiir tanrıları, epik şiir yalnız aşkı konu alır', 'Epik şiir kısa, lirik şiir çok uzundur', 'İkisi de yalnızca tiyatro sahnesinde söylenir'], 'Epik şiir olay örgüsü ve kahramanlık anlatısıyla, lirik şiir ise bireyin duygusu ve deneyimiyle ayrışır.'),
  ('Aristoteles\'e göre tragedyanın altı öğesi arasında en önemlisi olan öğe hangisidir?', 'Mythos (olay örgüsü)', ['Opsis (görüntü)', 'Melos (müzik)', 'Lexis (söyleyiş ve dil kullanımı)'], 'Aristoteles Poetika\'da olay örgüsünü tragedyanın \'ruhu\' sayar; karakter (ethos) ikinci sıradadır.'),
  ('Günümüze eksiksiz ulaşmış tek satyr oyunu hangisidir?', 'Euripides\'in Kyklops\'u', ['Aiskhylos\'un Prometheus\'u', 'Sophokles\'in İkhneutai\'si', 'Aristophanes\'in Kuşlar\'ı'], 'Kyklops, Odysseia\'daki Polyphemos bölümünü komik biçimde işler ve satyr oyunu türünü bütünüyle gösteren tek örnektir.'),
  ('Antik tiyatro oyuncularının maske takmasının başlıca sonucu aşağıdakilerden hangisidir?', 'Bir oyuncunun birden çok rol üstlenebilmesi', ['Seyircilerin oyunculardan korkması', 'Sahnede müziğin gereksizleşmesi', 'Kadın oyuncuların sahnede rol alması ve koronun kalkması'], 'Tragedyada oyuncu sayısı sınırlı ve hepsi erkekti; maskeler rol değişimini ve seyirciye karakterin duygusunu kolayca iletmeyi sağlıyordu.'),
  ('\'Tragedya\' sözcüğünün kökeniyle ilgili en yaygın açıklama hangisidir?', '\'Teke şarkısı\' anlamına gelen tragoidia sözcüğünden türemiştir', ['\'Kahraman\' ve \'şarkı\' anlamlarına gelen sözcüklerden türemiştir', '\'Gözyaşı\' anlamına gelen sözcükten türemiştir', '\'Perde\' anlamına gelen sözcükten türemiştir'], 'Tragos \'teke\', oide \'şarkı\' demektir; köken Dionysos şenliklerindeki koro şarkılarına bağlanır, ancak açıklama kesin değildir.'),
  ('Aiskhylos\'un Persler tragedyası, Yunan tragedya geleneğinde hangi yönüyle özel bir yere sahiptir?', 'Mitolojik değil, yakın tarihli bir olayı (Salamis) konu alan günümüze ulaşan tek tragedyadır', ['Tüm rolleri koronun oynadığı tek tragedyadır', 'Doğrudan komedya ile birleştirilmiş tek tragedyadır', 'Kadın oyuncuların rol aldığı ilk tragedyadır'], 'Persler, Pers saraylılarının Salamis yenilgisini öğrenmesini anlatır; Yunan tragedyalarında tarihsel konu nadirdir.'),
  ('Aiskhylos\'un Persler tragedyası olayları hangi sarayın içinde ve kimin gözünden anlatır?', 'Pers sarayında, yenilen tarafın bakışından', ['Atina meclisinde, kazanan tarafın bakışından ve zaferin gölgesinde', 'Delphoi tapınağında, kâhinin bakışından', 'Sparta\'da kralların bakışından'], 'Eser, Atina\'nın zaferini düşmanın acısını göstererek anlatır; bu da trajedinin insani boyutunu öne çıkarır.'),
  ('Aiskhylos\'un kendi mezar yazıtında şair kimliğini değil de hangi olaydaki savaşçılığını öne çıkardığı söylenir?', 'Marathon Savaşı', ['Termopylai Savaşı', 'Salamis Deniz Savaşı', 'Plataiai Savaşı'], 'Gela\'daki mezar yazıtının, ozanlığından söz etmeyip Marathon\'da savaştığını andığı bildirilir.'),
  ('Aiskhylos\'un Oresteia üçlemesinin sonunda Orestes\'in davası nerede ve kimin başkanlığında görülür?', 'Atina\'da Areopagos\'ta, Athena\'nın başkanlığında', ['Delphoi\'da Apollon\'un önünde', 'Argos\'ta Kreon\'un huzurunda', 'Sparta\'da Menelaos\'un başkanlığındaki ihtiyarlar meclisinde'], 'Erinyelerin kovaladığı Orestes için jüri oy verir; eşit çıkan oylarda Athena beraat yönünde oy kullanır.'),
  ('Aşağıdakilerden hangisi günümüze ulaşan yedi Aiskhylos tragedyasından biridir?', 'Yedi Kişi Thebai\'ye Karşı', ['Medea', 'Bakkhalar', 'Aias'], 'Aiskhylos\'tan yedi oyun kalmıştır; Medea ve Bakkhalar Euripides\'e, Aias ise Sophokles\'e aittir.'),
  ('Aiskhylos\'un tragedyası Sophokles\'inkiyle karşılaştırıldığında hangi özelliği öne çıkar?', 'Koroyu ön planda tutan, daha ağır ve görkemli anlatım', ['Üç oyunculu sahne kullanımı ve karakter çatışması ağırlığı', 'Sahne ressamlığı', 'Salt monolog kullanımı'], 'Aiskhylos\'ta koronun ağırlığı daha fazladır; Sophokles üçüncü oyuncuyu ve karakter çatışmasını öne çıkarır.'),
  ('Sophokles\'in Aias oyununda kahramanı delirmeye ve intihara götüren olay hangisidir?', 'Akhilleus\'un zırhının Odysseus\'a verilmesi', ['Agamemnon\'un onu kovması', 'Athena\'ya adak adayıp bunu yerine getirmemesi', 'Helene\'nin kaçırılması'], 'Zırhı alamayan Aias öfkeyle Akha ordusunu yok etmek ister; Athena onu deliye çevirir, sürüyü öldürür ve utançla kendi kılıcına kapanır.'),
  ('Sophokles\'in Philoktetes oyununda Philoktetes neden Lemnos adasında bırakılmıştı?', 'Yılan sokması yüzünden yarasının kokusu orduyu rahatsız ettiği için', ['Odysseus\'la kavga ettiği için', 'Aşk yüzünden', 'Gemi battığı için'], 'Philoktetes yaralı ve yalnızdır; yine de Truva\'nın alınması için onun Herakles\'ten kalan yayı gerekir.'),
  ('Sophokles\'in Philoktetes oyununda Philoktetes\'i ikna etmeye gönderilen genç kahraman kimdir?', 'Neoptolemos', ['Telemakhos', 'Orestes', 'Haimon'], 'Akhilleus\'un oğlu Neoptolemos, Odysseus\'un hilesine ortak olur; ancak Philoktetes\'e acıyıp doğruyu söylemeyi seçer.'),
  ('Sophokles\'in Elektra oyunu, Aiskhylos\'un Oresteia\'sındaki hangi olayı farklı bir bakışla işler?', 'Orestes\'in babasının intikamı için annesini öldürmesi', ['Truva atının yapılması', 'Prometheus\'un ateşi çalıp insanlara vermesi nedeniyle cezalandırılması', 'Oidipus\'un sürgünü'], 'Sophokles, çatışmayı Elektra\'nın iç dünyası ve kararlılığı üzerinden anlatır.'),
  ('Kral Oidipus\'ta Teiresias, kral Oidipus\'a ne söyleyince aralarında ağır bir tartışma çıkar?', 'Thebai\'yi lanetleyen katilin Oidipus\'un kendisi olduğunu', ['Sphinks\'in tekrar geldiğini', 'Kreon\'un tahtı ele geçirmek için Thebai\'yi terk edeceğini', 'Iokaste\'nin hasta olduğunu'], 'Oidipus kehaneti kabul edemez; Teiresias ve Kreon\'u komplo kurmakla suçlar.'),
  ('Kral Oidipus\'un sonunda Oidipus kendini nasıl cezalandırır?', 'Iokaste\'nin broşlarıyla gözlerini kör eder', ['Kendini uçurumdan atar', 'Thebai\'den kaçar ve bir daha geri dönmeyip yoksul yaşar', 'Kılıçla kendini öldürür'], 'Iokaste gerçeği öğrenince kendini asar; Oidipus onun broşuyla gözlerini oyar.'),
  ('Sophokles\'in Oidipus Kolonos\'ta oyunu neyi anlatır?', 'Kör ve sürgün Oidipus\'un Atina yakınında huzurla ölüşünü', ['Truva\'nın yıkılışını', 'Antigone\'nin Kreon tarafından idam edilişini ve mağarada ölüşünü', 'Orestes\'in yargılanışını'], 'Oidipus Kolonos\'ta Theseus\'un korumasında gizemli bir biçimde ölür; bu oyun Sophokles\'in ölümünden sonra sahnelenmiştir.'),
  ('Sophokles\'in Trakhisli Kadınlar oyununda Herakles\'in ölümüne yol açan şey nedir?', 'Eşi Deianeira\'nın gönderdiği zehirli gömlek', ['Hydra\'nın kanı', 'Kerberos\'un ısırığı ve Hades\'in laneti ile ölmesi', 'Atina\'nın kılıcı'], 'Deianeira, Nessos\'un kanına bulanmış gömleği aşkı geri getirir sanarak gönderir; gömlek Herakles\'i yakar.'),
  ('Sophokles\'in Atina\'da kamu görevleri üstlendiği, askerî komutanlığa seçildiği konusunda en çok anılan olay hangisidir?', 'Samos Savaşı', ['Marathon Savaşı', 'Sicilya Seferi', 'Peloponnesos Savaşı\'nın bitişi'], 'Sophokles Perikles ile birlikte strategos seçilmiş ve Samos\'a karşı sefere katılmıştır.'),
  ('Aşağıdakilerden hangisi Sophokles\'in tragedyaya getirdiği yeniliklerden biri sayılır?', 'Üçüncü oyuncuyu sahneye eklemesi', ['Satyr oyununu icat etmesi', 'Koroyu kaldırması', 'Tragedyayı tamamen düzyazıyla ve koro olmadan yazması'], 'Aristoteles\'e göre Sophokles üçüncü oyuncuyu getirerek diyalog ve karakter çatışmasını zenginleştirdi.'),
  ('Euripides\'in Bakkhalar oyununda Pentheus nasıl ölür?', 'Dionysos\'un çılgına çevirdiği annesi ve kadınlar tarafından parçalanır', ['Tanrının yıldırımıyla', 'Atlı bir saldırıda', 'Zehirli şarap içerek'], 'Dionysos\'a karşı çıkan Thebai kralı Pentheus, annesi Agave tarafından aslan sanılarak öldürülür.'),
  ('Euripides\'in Aulis\'te Iphigeneia oyunu hangi çatışmayı işler?', 'Agamemnon\'un seferin rüzgârı için kızını Artemis\'e kurban etmek zorunda kalması', ['Hektor ve Akhilleus\'un dövüşü', 'Odysseus\'un delilik taklidi', 'Orestes\'in anne katilliği'], 'Baba ile kral kimliği arasında kalan Agamemnon, ordunun baskısıyla kızını kurban etmeye razı olur.'),
  ('Euripides, yaşamının son yıllarını hangi bölgede geçirmiştir?', 'Makedonya', ['Sicilya', 'Mısır', 'Pers kralının sarayında sürgün olarak'], 'Atina\'dan ayrılan Euripides, Makedonya kralı Arkhelaos\'un sarayında yaşamış ve orada ölmüştür.'),
  ('Euripides\'in oyunlarının Sophokles ve Aiskhylos\'unkilerden ayrılan başlıca yanı aşağıdakilerden hangisidir?', 'Tanrı ve kahramanları insani zaaflarıyla, eleştirel ve gerçekçi biçimde işlemesi', ['Yalnız tarihsel konuları işlemesi', 'Koroyu tamamen kaldırması', 'Hiç trajik son kullanmaması'], 'Euripides\'te kadınların, kölelerin ve sıradan insanların psikolojisi öne çıkar; bu nedenle \'psikolojik gerçekçiliğin öncüsü\' sayılır.'),
  ('Euripides\'in oyunlarında sıklıkla kullanılan açılış monoloğu (prolog) ne işe yarar?', 'Olayın geçmişini ve durumu seyirciye baştan bildirmeye', ['Koroyu sahneden çıkarmaya', 'Sonucu gizlemeye', 'Tanrıların yargısını duyurup oyunun sonucunu seyirciye bildirmeye'], 'Euripides tragedyaları genellikle bir tanrı ya da kişinin geçmişi anlatan konuşmasıyla başlar.'),
  ('Euripides\'in Elektra oyununda Elektra\'nın evlendiği kişi kimdir?', 'Yoksul bir çiftçi', ['Pylades', 'Aigisthos', 'Orestes'], 'Aigisthos, Elektra\'nın soylu biriyle evlenip intikamcı bir oğul doğurmasını önlemek için onu yoksul bir köylüye vermiştir.'),
  ('Euripides\'in Ion oyununun kahramanı Ion hangi yerde büyür?', 'Delphoi tapınağında', ['Atina Akropolis\'inde', 'Mykene sarayında', 'Dodona\'da'], 'Apollon\'un oğlu Ion Delphoi\'de rahip olarak büyür; sonunda annesi Kreousa\'yı bulur.'),
  ('Aristophanes\'in Bulutlar komedyasında borçlarından kurtulmak isteyen Strepsiades, oğlunu nereye gönderir?', 'Sokrates\'in Düşünce Okulu\'na', ['Atina meclisinin kürsüsüne ve halk kurultayına', 'Delphoi kâhinine', 'Spartalı komutanın yanına'], 'Strepsiades hukuk hilelerini öğrensin diye oğlunu okula yollar; oğlu ise babasını dövmeye varacak kadar sofistleşir.'),
  ('Aristophanes\'in Kuşlar komedyasında Peisetairos ve Euelpides\'in kurduğu hayalî kentin adı nedir?', 'Bulutkuşluk Kenti (Nephelokokkygia)', ['Hyperborea (kuzeydeki efsanevi ülke)', 'Utopia', 'Atlantis'], 'İnsanlarla tanrılar arasına kurulan kuşlar kenti, tanrılara giden dumanı keserek onları açlığa mahkûm eder.'),
  ('Aristophanes\'in Barış (Eirene) komedyasında Trygaios, tanrılardan barışı geri getirmek için Olympos\'a nasıl çıkar?', 'Dev bir bokböceğinin sırtında', ['Kanatlı bir atla', 'Tahta bir merdivenle', 'Bir kartalın pençesinde, tanrıların izniyle'], 'Oyundaki saçma, abartılı yolculuk Eski Komedya\'nın kaba güldürü ve fantezi gücünü gösterir.'),
  ('Menandros\'un temsil ettiği Yeni Komedya\'nın tipik konularından biri hangisidir?', 'Zengin kızlarla yoksul gençlerin aşkı, karışıklık ve tanıma sahneleri', ['Doğrudan siyasi liderlerin hicvi', 'Tanrıların savaşı', 'Tarihî zaferlerin anlatımı'], 'Yeni Komedya gündelik aile içi sorunları, yanlış tanımaları ve mutlu sonları işler; Roma komedyasını etkilemiştir.'),
  ('Menandros\'un günümüze neredeyse eksiksiz ulaşan komedyası hangisidir?', 'Dyskolos (Huysuz Adam)', ['Lysistrata (Aristophanes\'in komedisi)', 'Bulutlar', 'Alkestis'], 'Dyskolos, 20. yüzyılda bulunan bir papirüsten bilinir; Menandros\'un diğer oyunları parçalar halindedir.'),
  ('Roma komedya yazarları Plautus ve Terentius hangi Yunan ozanın eserlerini model almıştır?', 'Menandros\'un Yeni Komedya\'sını', ['Aristophanes\'in Eski Komedya\'sını', 'Aiskhylos\'un tragedyalarını', 'Pindaros\'un şiirlerini'], 'Plautus ve Terentius Yeni Komedya kalıplarını Latinceye uyarlamış, bu geleneğin Avrupa komedyasına aktarılmasını sağlamıştır.'),
  ('Platon, Devlet\'te şairleri ideal devletinden dışlama gerekçesi olarak neyi öne sürer?', 'Şiirin gerçekliğin taklidinin taklidi olduğunu ve duyguları şımarttığını', ['Şiirin yalnız tanrılara hizmet ettiğini', 'Şiirin çok zor anlaşıldığını', 'Şiirin sadece zenginlere seslendiğini'], 'Platon\'a göre sanatçı idealar dünyasının gölgesi olan nesneleri taklit eder; bu nedenle hakikatten üç derece uzaktır.'),
  ('Platon, taklit kuramını açıklarken hangi nesneyi örnek verir?', 'Yatak', ['Lyra', 'Gemi', 'Tapınak'], 'İdea olarak yatak, marangozun yaptığı yatak ve ressamın resmettiği yatak aracılığıyla üç kademe oluşur.'),
  ('Platon\'un İon diyaloğunda şiirin kaynağı nasıl açıklanır?', 'Tanrısal bir ilhamdan, yani şairin coşku içinde kendinden geçmesinden', ['Okul eğitiminden', 'Tarihsel bilgiden', 'Ticaret deneyiminden'], 'Sokrates, şairin ve rhapsodosun bilgiyle değil tanrısal esinle (enthousiasmos) konuştuğunu söyler.'),
  ('Platon\'un Şölen (Symposion) diyaloğunda Aristophanes, aşkı hangi mitle açıklar?', 'İnsanların bir zamanlar çift olduğu, sonra ikiye bölünüp yarısını aradığı mitiyle', ['Eros\'un Zeus\'un oğlu olduğu mitiyle', 'Pandora\'nın kutusu mitiyle', 'Prometheus\'un ateşi mitiyle'], 'Her insan kaybettiği yarısını arar; aşk bu bütünlük özleminin adıdır.'),
  ('Şölen\'de Sokrates, aşk üzerine bilgiyi kimden öğrendiğini söyler?', 'Mantineialı Diotima\'dan', ['Aspasia\'dan', 'Sappho\'dan', 'Antigone\'den'], 'Diotima, aşkın güzelden başlayıp en yüksek güzelliğe yükselen bir basamak olduğunu öğretir.'),
  ('Aristoteles, Poetika\'da tarihçi ile şair arasındaki farkı nasıl açıklar?', 'Tarihçi olanı, şair olabilecek olanı anlatır', ['Tarihçi uydurur, şair gerçeği aktarır', 'İkisi de aynı işi yapar', 'Şair yalnız tanrıları, tarihçi insanları anlatır'], 'Bu nedenle Aristoteles şiirin tarihten daha felsefi ve daha evrensel olduğunu söyler.'),
  ('Poetika\'da tragedyanın \'bir güneş turu\' kadar sürmesi gerektiğine dair görüş, sonradan hangi kurala dönüştürülmüştür?', 'Zaman birliği', ['Yer birliği', 'Olay birliği', 'Kişi birliği'], 'Aristoteles tavsiye düzeyinde söylemiş; Rönesans ve klasisizm kuramcıları bunu katı \'üç birlik\' kuralına çevirmiştir.'),
  ('Thukydides\'in Peloponnesos Savaşı Tarihi\'nin Herodotos\'tan ayrılan temel yaklaşımı hangisidir?', 'Tanrısal açıklamaları dışlayıp insan doğası ve siyasal nedenlere yönelmesi', ['Efsane ve masalları ön plana çıkarması', 'Mısır\'ın gezi notlarını yazması', 'Şiirle yazması'], 'Thukydides olayları çağdaşı olarak izler ve tanrısal müdahale yerine güç, korku ve çıkarı ele alır.'),
  ('Ksenophon\'un Anabasis adlı eseri neyi anlatır?', 'Genç Kyros\'un seferine katılan Yunan paralı askerlerinin Pers topraklarından denize dönüşünü', ['Truva Savaşı\'nın nedenlerini', 'Büyük İskender\'in Hindistan seferini', 'Atina\'nın kuruluşunu'], 'On bin askerin Kunaksa yenilgisinden sonra Karadeniz kıyısına ulaşıp \'Deniz! Deniz!\' diye bağırdığı sahne ünlüdür.'),
  ('Ksenophon\'un Sokrates\'in anılarını topladığı eseri hangisidir?', 'Memorabilia (Hatıralar)', ['Anabasis', 'Kyropaideia (Büyük Kyros\'un eğitimi)', 'Oikonomikos'], 'Memorabilia, Sokrates\'in ahlak anlayışını ve konuşmalarını bir öğrencinin gözünden aktarır.'),
  ('Plutarkhos\'un Paralel Yaşamlar adlı eserinin kurgusu nasıldır?', 'Bir Yunan ile bir Romalı büyük adamın biyografisi karşılaştırmalı ikili halinde sunulur', ['Yalnız Yunan komutanların hayatları yer alır', 'Tanrıların yaşamları sırayla anlatılır', 'Şairlerin hayat hikâyeleri yazılır'], 'Eser, ahlaki karakterleri ikili karşılaştırmayla gösterir; Aleksandros ile Caesar gibi çiftler bulunur.'),
  ('Hellenistik dönemde Yahudi kutsal metinlerinin İskenderiye\'de Yunancaya çevrilmesiyle ortaya çıkan çeviri hangisidir?', 'Septuaginta', ['Vulgata', 'Peşitta', 'Targum'], 'Septuaginta yaklaşık yetmiş kişinin çevirdiği söylentisinden adını alır ve sonraki Hıristiyan Eski Ahit geleneğine temel olmuştur.'),
  ('Hellenistik çağda Atina\'dan İskenderiye\'ye kayan edebiyat merkezinin yaşam alanı olarak en çok hangi kurumla anılır?', 'Mouseion', ['Akademia', 'Lykeion', 'Olimpiyat Spor Alanı'], 'Mouseion, bilginlerin devlet desteğiyle yaşadığı araştırma merkezi olarak filoloji ve şiir çalışmalarına ev sahipliği yaptı.'),
  ('Aeneis\'in ilk altı kitabı ile son altı kitabı, hangi Homeros destanlarına koşut biçimde kurulmuştur?', 'İlk yarı Odysseia\'ya, ikinci yarı İlyada\'ya', ['İlk yarı İlyada\'ya, ikinci yarı Odysseia\'ya benzetilmiştir', 'Her iki yarı da yalnız Odysseia\'ya', 'Her iki yarı da yalnız İlyada\'ya'], 'Aeneas\'ın deniz yolculuğu Odysseia\'yı, İtalya\'daki savaş ise İlyada\'yı andırır.'),
  ('Aeneas\'ın karakterini en iyi anlatan sıfat hangisidir ve Vergilius onu hangi değerle özdeşleştirir?', 'Pius; tanrılara, aileye ve vatana bağlılık', ['Callidus; kurnazlık, hile ve zekâ üstünlüğü sevgisi', 'Ferox; yırtıcılık', 'Superbus; kibir'], 'Roma ahlakının temel değeri olan pietas, Aeneas\'ı Odysseus\'un kurnazlığından ve Akhilleus\'un öfkesinden ayırır.'),
  ('Aeneis\'te Aeneas\'ın yeraltında babasından öğrendiği geleceğe dair büyük görüntü neyi anlatır?', 'Roma\'nın ve soyundan gelecek ünlülerin geleceğini', ['Truva\'nın yeniden kuruluşunu ve Yunan şehirlerinin kaderini', 'Tanrıların iflasını', 'Kartaca\'nın zaferini'], 'Anchises, Aeneas\'a Augustus\'a kadar gelecek Roma önderlerini gösterir; destan böylece Roma\'nın tarihsel misyonunu yüceltir.'),
  ('Vergilius\'un ölürken Aeneis hakkında verdiği iddia edilen buyruk nedir?', 'Eserin yakılması', ['Eserin Augustus\'a ithaf edilmesi', 'Eserin Yunancaya çevrilmesi', 'Eserin kısaltılması'], 'Eseri bitiremediğini düşünen şair yakılmasını istemiş, ancak Augustus bunu reddederek yayımlatmıştır.'),
  ('Catullus\'un şiirlerinde adını taşıyan sevgili \'Lesbia\' çoğunlukla kim olarak yorumlanır?', 'Clodia', ['Cynthia', 'Delia', 'Corinna'], 'Lesbia adının Sappho\'nun Lesbos\'una gönderme yaptığı ve gerçek kişinin Clodia olduğu düşünülür.'),
  ('Ovidius\'un Ars Amatoria (Aşk Sanatı) adlı yapıtı, onun Augustus tarafından sürülmesindeki iki gerekçeden biri olarak sayılır. Bu eserin içeriği nedir?', 'Aşk ve flört üzerine alaycı bir öğreti şiiri', ['Roma tarihinin kısa özetlendiği ciddi bir destan', 'Tarım takvimi', 'Savaş taktikleri'], 'Ovidius sürgün nedeniyle \'bir şiir ve bir hata\'dan söz eder; Aşk Sanatı Augustus\'un ahlak reformlarıyla çatışmıştır.'),
  ('Ovidius\'un Heroides adlı yapıtı hangi biçimde yazılmıştır?', 'Mitolojik kadın kahramanların sevgililerine yazdığı mektup-şiirler', ['Savaş destanı', 'Komedya', 'Tarım şiiri'], 'Penelope\'den Odysseus\'a, Dido\'dan Aeneas\'a mektuplar gibi şiirler, kadın bakışını öne çıkarır.'),
  ('Horatius\'a atfedilen \'Ut pictura poesis\' deyişi neyi ifade eder?', 'Şiir resim gibidir', ['Şiir müziğin kardeşidir', 'Şiir tarih gibidir', 'Şiir tiyatrodan doğar'], 'Bu söz sonraki sanat kuramlarında şiir ve resim arasındaki ilişki tartışmalarına kaynaklık etmiştir.'),
  ('Roma edebiyatının başlangıcı olarak anılan Livius Andronicus\'un yaptığı çalışma nedir?', 'Odysseia\'yı Latinceye çevirmek', ['Aeneis\'i yazmak', 'Cicero\'nun söylevlerini toplamak', 'Plautus\'un oyunlarını sahnelemek'], 'Latin edebiyatı, Yunan eserlerinin çevirisi ve uyarlanmasıyla başlar.'),
  ('Cicero\'nun \'Quo usque tandem, Catilina\' diye başlayan konuşmaları neyi hedef alır?', 'Cumhuriyeti devirmeyi planlayan Catilina komplosunu', ['Pompeius\'un seferlerini', 'Caesar\'ın diktatörlüğünü ve senatoyu etkisizleştirmesini', 'Sicilya valisini'], 'Cicero konsüllüğü sırasında senatoda Catilina\'yı sert biçimde suçlamıştır.'),
  ('Tacitus\'un Germania adlı eseri hangi konuyu işler?', 'Germen kabilelerinin yaşamı ve gelenekleri', ['Britanya\'nın fethi', 'Roma yasaları', 'İskenderiye\'nin tarihi ve Hellenistik krallıklar'], 'Tacitus, Germen halklarını sade yaşamları ve ahlaki değerleriyle Roma toplumuyla karşılaştırarak anlatır.'),
  ('Genç Plinius\'un mektuplarının tarihsel değeri hangi olaya tanıklık etmesinden gelir?', 'Vezüv\'ün Pompeii\'yi gömen patlamasına', ['Roma\'nın yangınına ve Neron\'un saray hayatına tanıklık etmesine', 'Truva\'nın düşüşüne', 'Aktium savaşına'], 'Plinius, amcasının ölümünü ve patlamayı Tacitus\'a yazdığı mektuplarda anlatır.'),
  ('Plautus\'un Aulularia (Küp) adlı komedisi hangi sonraki yazarın Cimri oyununa kaynaklık etmiştir?', 'Molière', ['Shakespeare', 'Goldoni', 'Lope de Vega'], 'Eski bir küp dolusu altına saplanan Euclio tipi, Harpagon karakterinin kaynağıdır.'),
  ('Terentius\'a ait \'Homo sum, humani nihil a me alienum puto\' sözü neyi anlatır?', 'İnsan olduğum için insana ait hiçbir şeyi yabancı saymıyorum', ['Savaş kaçınılmazdır', 'Tanrılar adildir', 'Ölüm bir kurtuluştur'], 'Söz, insanlık değerleri ve hoşgörü anlayışının simgesi olarak anılır.'),
  ('Boethius\'un Felsefenin Tesellisi (De Consolatione Philosophiae) hangi koşullarda yazılmıştır?', 'Hapishanede idam beklerken', ['Savaş sırasında', 'Deniz yolculuğunda', 'Sürgünde, uzak bir adada ve yoksulluk içinde'], 'Boethius, haksız mahkûmiyetinin ardından Felsefe kişisini karşısında görerek diyalog içinde teselli bulur; eser ortaçağda çok okunmuştur.'),
  ('\'İnanna\'nın Yeraltına İnişi\' öyküsünde İnanna her kapıdan geçerken ne yapmak zorunda kalır?', 'Üzerindeki bir giysi ya da takıyı çıkarmak', ['Bir şarkı söylemek', 'Bir hayvan kurban edip kanını sunmak zorunda kalmak', 'Bir bilmeceyi çözmek'], 'Yedi kapıdan geçerken sembolik güç eşyalarını bırakan İnanna, yeraltı kraliçesi Ereşkigal\'in önüne çıplak ve güçsüz varır.'),
  ('İnanna yeraltından dönerken yerine ölüler diyarına kimin gönderilmesi gerekir?', 'Eşi Dumuzi\'nin', ['Kardeşi Utu\'nun', 'Ereşkigal\'in', 'Enki\'nin'], 'Dumuzi, İnanna\'nın yasına katılmadığı için yeraltına gönderilir; bu öykü mevsim döngüsüyle bağdaştırılır.'),
  ('Hammurabi Kanunları, edebî ve hukuki metin olarak hangi kayıt biçimiyle günümüze ulaşmıştır?', 'Taş bir steli üzerine yazılmış çivi yazısı metni olarak', ['Papirüs ruloları halinde', 'Deri tomarlarda', 'Mağara duvarlarında'], 'Hammurabi\'nin yasaları Babil dilinde yazılmıştır ve Louvre\'daki diyorit steliyle tanınır.'),
  ('Sümerce \'Gılgamış ve Agga\' gibi öyküler, hangi çağın anlatı geleneğine örnektir?', 'Sümer kahramanlık anlatılarına', ['Hitit kral listelerine', 'Mısır\'ın bilgelik ve öğüt edebiyatına', 'Pers saray şiirine'], 'Gılgamış\'ın Sümerce şiirleri, sonraki Akadça Gılgamış Destanı\'na kaynak olan bağımsız anlatılardır.'),
  ('Gılgamış Destanı\'nın günümüze en tam ulaşan Babil versiyonu kaç tablete yazılmıştır?', 'On iki', ['Altı', 'Dokuz', 'Yirmi dört'], 'Standart Babil versiyonu on iki tablettir ve Sin-leqi-unninni tarafından düzenlendiği kabul edilir.'),
  ('George Smith\'in 1872\'de tabletten okuyup duyurduğu ve Batı\'da büyük ilgi uyandıran bölüm hangisidir?', 'Tufan öyküsü', ['Ölüler diyarı yolculuğu', 'Humbaba\'nın ölümü', 'Boğa savaşı'], 'Smith\'in duyurusu Tevrat\'taki tufanla benzerliği nedeniyle sansasyon yarattı.'),
  ('Enkidu, Uruk\'a gelmeden önce yabanıl yaşamdan nasıl uzaklaştırılır?', 'Tapınak kadını Şamhat\'la geçirdiği günlerle', ['Gılgamış\'ın kendisine verdiği hediyelerle', 'Tanrıların buyruğuyla', 'Bir av sırasında'], 'Şamhat\'la altı gün yedi gece birlikte kalan Enkidu, hayvanlar arasındaki yaşamından kopar ve medeniyete geçer.'),
  ('Gılgamış\'ın hem tanrısal hem insani yönü, destanın hangi merkezî çatışmasını doğurur?', 'Ölümsüzlük arzusu ile ölümlü olmanın kaçınılmazlığı', ['Kral ile halk çatışması', 'Doğu ile Batı çatışması', 'Erkek ile kadın çatışması'], 'Gılgamış yarı tanrı olmasına karşın ölümlü olduğu için bu çatışma onun yolculuğunu şekillendirir.'),
  ('Mısır edebiyatında \'Sinuhe\'nin Öyküsü\' hangi konuyu işler?', 'Bir saray görevlisinin ülkeden kaçıp yıllar sonra geri dönmesini', ['Bir savaşçının Nil kıyısında tanrıyla karşılaşıp kral olmasını', 'Bir firavunun gençliğini', 'Bir köylünün hazine bulmasını'], 'Orta Krallık\'ın klasik anlatısı olan öykü, sürgün, kimlik ve eve dönüş temalarını işler.'),
  ('Mısır\'ın bilgelik edebiyatına örnek olarak gösterilen Ptahhotep\'in Öğütleri neyi içerir?', 'Gençlere yönelik ahlak ve davranış öğütlerini', ['Savaş şarkılarını', 'Tapınak yasalarını', 'Büyü formüllerini'], 'Ptahhotep, vezir olarak yaşlılık ve toplumsal davranış konusunda oğluna tavsiyelerde bulunur.'),
  ('Vaiz Kitabı\'nda tekrarlanan \'Boşluk, her şey boşluk\' sözü yazarın hangi bakış açısını yansıtır?', 'Dünyevi çabaların geçiciliğine dair kötümser düşünceyi', ['Savaş çağrısını', 'Ticaret övgüsünü', 'Aşk tutkusunu'], 'Vaiz, zenginlik ve bilgelik peşinde koşmanın nihayetinde anlamsızlaştığını düşünür.'),
  ('Ölü Deniz Tomarları 1947\'de nerede bulunmuştur?', 'Kumran mağaralarında', ['Sinai Dağı\'nda', 'Ürdün Vadisi\'nde Eriha\'da', 'Ninova\'da'], 'Kumran buluntuları İbranice kutsal metinlerin en eski kopyalarını içerir.'),
  ('Chandogya Upanişad\'ındaki \'Tat tvam asi\' sözü ne anlama gelir?', 'O sensin', ['Her şey boştur', 'Dünya bir rüyadır', 'Doğru söyle'], 'Söz bireysel öz (atman) ile evrensel gerçeğin (Brahman) özdeşliğini anlatır.'),
  ('Hint geleneğinde Vedalar için kullanılan ve \'işitilmiş\' anlamına gelen kavram hangisidir?', 'Şruti', ['Smriti', 'Purana', 'Sutra'], 'Şruti, ilahi kaynaklı sayılan metinleri; smriti ise insanlarca hatırlanıp aktarılan metinleri belirtir.'),
  ('Mahabharata\'da Pandavaların krallığını kaybetmesine yol açan olay nedir?', 'Yudhişthira\'nın zar oyunuyla her şeyini yitirmesi', ['Draupadi\'nin kaçırılması', 'Arjuna\'nın sürgünü', 'Bhişma\'nın ölümü'], 'Duryodhana\'nın hileli zar oyununda Yudhişthira krallığını, kardeşlerini ve Draupadi\'yi kaybeder.'),
  ('Mahabharata\'da Kunti\'nin evlenmeden önce doğurduğu ve karşı safta savaşan oğlu kimdir?', 'Karna', ['Abhimanyu', 'Bhima', 'Duryodhana'], 'Güneş tanrısı Surya\'dan olan Karna, kardeşlerine karşı Kaurava\'ların yanında savaşır.'),
  ('Mahabharata\'da savaş sırasında ölüm döşeğine ok yatağına yatan yaşlı komutan kimdir?', 'Bhişma', ['Drona', 'Karna', 'Aşvatthama'], 'Bhişma, ölümü seçme hakkına sahip olduğu için ok yatağında günlerce bekler ve Yudhişthira\'ya öğütler verir.'),
  ('Rama\'nın on dört yıl ormanda yaşamak zorunda kalmasının nedeni nedir?', 'Kaikeyi\'nin kocasından aldığı iki vaat nedeniyle', ['Ravana\'nın lanetiyle', 'Babasının onu sınamak istemesiyle', 'Tanrıların buyruğuyla'], 'Kaikeyi, oğlu Bharata\'nın tahta çıkmasını ve Rama\'nın sürgününü ister; Dasharatha sözünü tutar.'),
  ('Ramayana\'da Ravana\'nın Sita\'yı kaçırmasına olanak sağlayan hile nedir?', 'Altın geyik görünümü ile Rama ve Lakshmana\'yı uzaklaştırması', ['Sita\'yı uyutması', 'Tanrılardan izin alması', 'Lanka\'ya kayıkla gelmesi'], 'Mariça, altın geyik kılığında Rama\'yı çekerken Ravana yalnız kalan Sita\'yı kaçırır.'),
  ('Kalidasa\'nın \'Bulut Haberci\' (Meghaduta) adlı uzun şiirinde sürgündeki yaksha, sevgilisine haberi nasıl gönderir?', 'Bir buluttan haberci olmasını isteyerek', ['Bir kuşa mektup bağlayarak', 'Rüzgârla şarkı göndererek', 'Bir yolcuya sözlü haber vererek ve ona hediye göndererek'], 'Yaksha Himalayalara doğru giden bulutun yolunu betimler ve sevgilisine mesaj taşımasını ister.'),
  ('Natyashastra\'nın Sanskrit edebiyatı ve sanat kuramındaki başlıca yeri nedir?', 'Drama, dans ve müzik üzerine temel ve kapsamlı kuram kitabı olması', ['İlk Sanskrit destanı olması', 'Vedaların yorumu olması', 'Hukuk kitabı olması'], 'Bharata Muni\'ye atfedilen Natyashastra, rasa kuramını da içerir ve Hint estetiğinin temelini oluşturur.'),
  ('Natyashastra\'daki \'rasa\' kavramı neyi anlatır?', 'Sanat eserinin izleyicide uyandırdığı estetik duygu tadını', ['Dize ölçüsünü', 'Kahramanın soyunu', 'Sahne dekorunu'], 'Rasa, aşk, kahkaha, acıma, öfke gibi temel duyguların estetik zevke dönüşmesini anlatır.'),
  ('Sanskrit dramasında soytarı gibi komik yardımcı rolünü üstlenen tip nedir?', 'Vidushaka', ['Sutradhara', 'Nayaka', 'Vita'], 'Vidushaka kralın dostu olarak dalgacı ve oburdur; ciddi sahnelerin arasına neşe katar.'),
  ('Jayadeva\'nın Gita Govinda adlı şiir eseri hangi aşk çiftini konu alır?', 'Radha ile Krişna', ['Rama ile Sita', 'Şiva ile Parvati', 'Nala ile Damayanti'], '12. yüzyılda yazılan eser, Radha ve Krişna\'nın aşkını bhakti anlayışıyla işler.'),
  ('Kabir\'in dohe adı verilen dizelerinde en çok hangi tutum öne çıkar?', 'Din ve kast ayrımlarını aşan, tek gerçeğe vurgu yapan bir bakış', ['Savaşa çağrı', 'Kralları övme', 'Katı ritüellere bağlılık'], 'Kabir 15. yüzyılda Hindu ve Müslüman ayrımına karşı çıkan mistik bir ozandı.'),
  ('Delhi\'de yaşamış, Farsça ve Hindi/Urdu kökenli dilde yazan, \'Hindistan\'ın papağanı\' diye anılan şair kimdir?', 'Amir Hüsrev Dehlevi', ['Gâlib', 'Mir Taki Mir', 'Kabir'], 'Amir Hüsrev, 13-14. yüzyılda Delhi\'de yaşayıp Farsça gazel ve Hindavi şiirleriyle öne çıkmıştır.'),
  ('Premchand\'ın Hintçe ve Urduca yazdığı \'Godan\' romanı hangi toplumsal sorunu işler?', 'Yoksul köylünün borç ve sömürü altında ezilmesini', ['Saray entrikalarını', 'Büyük şehirdeki işçi grevini', 'Dini savaşları'], 'Premchand, Hint köy yaşamını gerçekçi bir bakışla ele alan modern Hint romanının önemli ismidir.'),
  ('Tagore\'un \'Gitanjali\' adlı şiir kitabı hangi dilde yazılmış ve 1913 Nobel\'inde etkili olmuştur?', 'Bengalce yazılıp yazarın kendi İngilizce çevirisiyle tanınmıştır', ['Hintçe yazılıp Fransızca çevrilmiştir', 'Sanskritçe yazılıp Almanca çevrilmiştir', 'Urduca yazılıp Rusça çevrilmiştir'], 'Gitanjali \'Şarkı Sunuları\' demektir; İngilizce çevirisi Batı\'da büyük ilgi görmüştür.'),
  ('R. K. Narayan\'ın öykü ve romanlarının geçtiği hayalî Güney Hindistan kasabasının adı nedir?', 'Malgudi', ['Ayodhya', 'Kanchipuram', 'Madurai'], 'Narayan, Malgudi\'yi küçük kasaba yaşamının mizahi bir mikrokozmosu olarak kurmuştur.'),
  ('Dhammapada hangi tür metindir?', 'Buddha\'ya atfedilen ahlaki öğüt dizeleri derlemesi', ['Rahipler için hukuk kitabı', 'Destan', 'Tarih kroniği'], 'Pali dilinde yazılan Dhammapada, Theravada geleneğinin en çok okunan kısa metinlerindendir.'),
  ('Budist kanonu \'Tipitaka\' neden \'Üç Sepet\' diye anılır?', 'Vinaya, Sutta ve Abhidhamma olmak üzere üç bölümden oluştuğu için', ['Üç farklı dilde yazıldığı için', 'Üç ayrı tapınakta saklandığı için', 'Üç yüzyılda yazıldığı için'], 'Vinaya keşiş kuralları, Sutta konuşmalar, Abhidhamma ise felsefi analizlerdir.'),
  ('Milinda Panha\'da Kral Menandros\'un karşısında yer alan Budist bilge kimdir?', 'Nagasena', ['Aşvaghosha', 'Nagarjuna', 'Ananda'], 'Eser, Yunan kökenli Baktria kralı ile Nagasena arasındaki felsefi diyaloğu içerir.'),
  ('Aşvaghosha\'nın Buddhacarita\'sı hangi türdedir?', 'Buddha\'nın hayatını anlatan epik şiir', ['Komedya', 'Tarih', 'Hukuk'], 'Sanskrit kavya tarzında yazılan eser, Buddha\'nın doğumundan ölümüne yaşam öyküsünü anlatır.'),
  ('Konfüçyüs\'ün \'li\' kavramı hangi anlamları içerir?', 'Ayinler, görgü kuralları ve toplumsal uyum', ['Askerî disiplin', 'Ticaret kuralları', 'Doğaüstü güçler'], 'Li, aile ve devlet ilişkilerinde uyumu sağlayan ritüel ve görgü kurallarını kapsar.'),
  ('Konfüçyüs\'ün \'Başkasına yapılmasını istemediğin şeyi sen de yapma\' ilkesi etik açıdan neyi ifade eder?', 'Karşılıklılık ve empati ilkesini', ['Savaş stratejisini', 'Servet biriktirmeyi ve mal mülk edinmeyi', 'Doğaya uymayı'], 'Bu ifade \'altın kural\'ın olumsuz biçimi olarak yorumlanır.'),
  ('Chunqiu (Bahar ve Sonbahar Yıllıkları) hangi türdendir?', 'Tarih kaydı', ['Şiir', 'Roman', 'Tiyatro oyunu ve sahne metni'], 'Lu devletinin olaylarını yıl yıl kaydeden metin, geleneksel olarak Konfüçyüs\'e bağlanır.'),
  ('Taoizm\'de \'wu wei\' ilkesi neyi öğütler?', 'Doğaya karşı çıkmadan, zorlamadan eylemde bulunmayı', ['Savaşta her yolu denemeyi', 'Yalnız ritüelleri sürdürmeyi', 'Parayı çok biriktirmeyi'], 'Wu wei \'eylemsizlik\' değil, doğal akışa uygun eylemdir.'),
  ('Zhuangzi\'nin ünlü \'kelebek rüyası\' anlatısı ne sorgular?', 'Gerçeklik ile rüya arasındaki ayrımı ve benliğin kesinliğini', ['Savaşın nedenlerini', 'Krallığın yönetimini', 'Evlilik kurallarını'], 'Zhuangzi\'nin kelebek olduğunu mu yoksa kelebeğin Zhuangzi olduğunu mu düşlediği belirsizdir.'),
  ('Han Feizi\'nin temsil ettiği Legalizm okulu yönetimde neyi vurgular?', 'Katı yasa ve cezalandırma', ['Erdemli örnek ve ahlaki eğitim', 'Doğaya uyum', 'Ritüel görgü'], 'Legalizm insan doğasını bencil görerek düzen için ödül ve ceza sistemini şart koşar.'),
  ('Taoizm ile Konfüçyüsçülük arasındaki fark aşağıdakilerden hangisidir?', 'Taoizm doğal akışa uymayı, Konfüçyüsçülük toplumsal ahlakı öne çıkarır', ['Taoizm yalnızca ritüel, Konfüçyüsçülük yalnız doğa', 'Taoizm devleti öne alır, Konfüçyüsçülük bireyi', 'İkisi de aynı öğretidir'], 'Taoizm doğayla uyumu, Konfüçyüsçülük ise ahlaki sorumluluk ve ilişkileri vurgular.'),
  ('Chuci (Chu Şiirleri) geleneğinin başlıca şairi sayılan Qu Yuan\'ın en ünlü uzun şiiri hangisidir?', 'Li Sao (Ayrılığın Acısı)', ['Uzun Keder Şarkısı', 'Şeftali Çiçeği Pınarı (Tao Yuanming)', 'Gece Sessizliği'], 'Qu Yuan, sürgün edilince nehre atlamış; onu anma geleneği Ejderha Kayığı Festivali\'ne bağlanır.'),
  ('Tao Yuanming\'in şiirlerinde öne çıkan tutum hangisidir?', 'Memuriyeti bırakıp köy yaşamına dönme isteği', ['Savaş övgüsü', 'Saray yaşamı övgüsü', 'Ticaret hırsı'], 'Tao Yuanming, memurluktan ayrılıp çiftçilikle geçirdiği sade yaşamı yüceltmiştir.'),
  ('Wang Wei için söylenen \'şiirinde resim, resminde şiir var\' sözü neyi ifade eder?', 'Doğa tasvirlerinin görsel nitelikte olması', ['Savaş betimlemelerinin çok canlı olması ve abartılı bulunması', 'Müziğin şiirden üstün olması', 'Düzyazı ağırlığı'], 'Su Shi\'ye atfedilen bu söz, Wang Wei\'in hem şair hem ressam olmasını belirtir.'),
  ('Li Qingzhao\'nun Çin edebiyatı tarihindeki yeri nedir?', 'Song dönemi ci şiirinin en ünlü kadın şairi olması', ['İlk Çin romancısı olması', 'Tang tiyatrosunun ve operasının kurucusu olması', 'Konfüçyüs\'ün öğrencisi olması'], 'Li Qingzhao, sevgi, ayrılık ve sürgün acısını inceliklerle işlemiştir.'),
  ('Tang şiirinde dört dizeden oluşan kısa şiir biçimine ne ad verilir?', 'Jueju', ['Lüshi', 'Ci', 'Fu'], 'Jueju dört dize, lüshi ise sekiz dizelik düzenli biçimdir.'),
  ('Luo Guanzhong\'a atfedilen \'Üç Krallık Romanı\' hangi dönemi anlatır?', 'Han hanedanının çöküşünü izleyen Wei, Shu ve Wu krallıkları dönemini', ['Tang hanedanının kuruluşunu', 'Moğol işgalini', 'Qing hanedanının çöküşünü'], 'Liu Bei, Cao Cao, Sun Quan ve bilge Zhuge Liang gibi figürler romanın merkezindedir.'),
  ('\'Su Kıyısı\' (Shuihu Zhuan) romanında ana karakterler kimlerdir?', 'Liangshan bataklığında toplanan 108 haydut', ['Üç krallığın hükümdarları', 'Beş Klasik\'in öğrencileri', 'Altın Post\'u arayan Yunanlı denizciler ve kahramanlar'], 'Shi Nai\'an\'a atfedilen roman, adaletsiz yönetime isyan eden haydutların öyküsünü anlatır.'),
  ('Guan Hanqing\'in \'Dou E\'nin Haksızlığı\' oyunu hangi tür tiyatroya aittir?', 'Yuan dönemi zaju', ['Peking Operası', 'Kunqu', 'Gölge oyunu'], 'Haksız yere idam edilen genç kadının öyküsü, adaletsizliğe karşı doğanın tepkisini (yazın kar yağması) kullanır.'),
  ('Wang Shifu\'nun \'Batı Odası Öyküsü\' hangi konuyu işler?', 'İki gencin aile engellerine karşı aşkı', ['Savaş zaferi', 'Hanedan çöküşü', 'Tanrıların aralarındaki taht çekişmesi ve savaşları'], 'Yuan dönemi zaju\'sunun en popüler aşk oyunlarındandır.'),
  ('Lu Xun\'un \'Bir Delinin Güncesi\' adlı hikâyesi Çin edebiyatında hangi dönüm noktasını temsil eder?', 'Modern Çin edebiyatının ve halk dilinin (baihua) başlangıcı', ['Konfüçyüsçü klasiklerin yükselişi', 'Tang şiirinin doğuşu', 'Ming romanının yeniden doğuşu'], '1918\'de yayımlanan hikâye, feodal gelenekleri \'yamyamlık\' olarak eleştirir.'),
  ('Man\'yoshu için hangisi doğrudur?', 'Yaklaşık dört bin beş yüz şiir içeren en eski Japon şiir antolojisidir', ['Yalnız haiku içeren bir derlemedir', 'Kadın yazarların günlükleridir', 'Noh oyunlarının derlemesidir'], '8. yüzyılda derlenen Man\'yoshu, imparatordan köylüye farklı kesimlerden şiirler içerir.'),
  ('Taketori Monogatari (Bambu Kesicinin Öyküsü) neyle tanınır?', 'Bambu içinde bulunan Kaguya-hime\'nin öyküsüyle', ['Bir savaşçının onuru için intihar edişiyle', 'Bir keşişin gezisiyle', 'Bir ressamın aşkıyla'], 'Japon edebiyatının en eski anlatılarından sayılan masalda ay prensesi sonunda aya döner.'),
  ('Heike Monogatari\'de hangi temel duygu veya görüş öne çıkar?', 'Her şeyin geçici olduğu (mujo) düşüncesi', ['Savaşın kutsallığı ve samuray onuru', 'Servet hırsı', 'Aşkın zaferi'], 'Eser, Taira ailesinin yükselişi ve yıkılışını Budist geçicilik anlayışıyla anlatır.'),
  ('Heike Monogatari\'yi anlatan gezgin kör rahiplerin kullandığı çalgı hangisidir?', 'Biwa', ['Koto', 'Shamisen', 'Shakuhachi'], 'Biwa hoshi denen çalgıcılar, destanı biwa eşliğinde okuyarak yaymıştır.'),
  ('Yoshida Kenko\'nun \'Tsurezuregusa\' adlı eseri hangi türün örneğidir?', 'Zuihitsu (rasgele düşünceler / deneme)', ['Waka antolojisi (imparatorluk derlemesi)', 'Noh oyunu', 'Savaş anlatısı'], '\'Boş Zamanların Denemeleri\', Budist geçicilik duygusuyla günlük gözlemleri karıştırır.'),
  ('\'Mono no aware\' kavramı Japon estetiğinde neyi anlatır?', 'Şeylerin geçiciliğine duyulan duygusal incelik', ['Savaş cesareti', 'Zenginlik', 'Sessiz kalma'], 'Kavram, kiraz çiçeklerinin dökülmesi gibi geçici güzellikler karşısında duyulan hüzünlü hayranlığı anlatır.'),
  ('Noh tiyatrosunun kuramcısı olarak bilinen ve estetik ilkesi \'yugen\' ile anılan kişi kimdir?', 'Zeami', ['Chikamatsu', 'Basho', 'Saikaku'], 'Zeami, 14-15. yüzyılda Noh\'un biçimini ve gizemli güzellik anlayışını kuramlaştırmıştır.'),
  ('Noh oyunlarında aralara girerek gündelik yaşamı komik biçimde anlatan kısa oyunlara ne ad verilir?', 'Kyogen', ['Kabuki', 'Bunraku', 'Rakugo'], 'Kyogen, Noh\'un ciddi ve ağır havasını dengeleyen konuşma ağırlıklı güldürüdür.'),
  ('Kabuki\'nin kurucusu olarak anılan kadın sanatçı kimdir?', 'Izumo no Okuni', ['Murasaki Şikibu', 'Sei Şonagon', 'Higuchi Ichiyo'], '17. yüzyıl başında Kyoto\'da dans ve skeçlerle başlayan Kabuki, sonradan yalnızca erkek oyuncuyla sahnelenmiştir.'),
  ('Matsuo Başo\'nun \'Oku no Hosomichi\' (Kuzeyin Dar Yolları) adlı eseri hangi türdendir?', 'Şiir ve düzyazı karışımı gezi günlüğü', ['Noh oyunu', 'Savaş destanı', 'Hukuk metni'], 'Başo, kuzey Japonya yolculuğunu düzyazı ve haikularla anlatır.'),
  ('Haiku\'nun öncüsü olan zincirleme şiir biçimine ne ad verilir?', 'Renga', ['Waka', 'Zuihitsu', 'Kanshi'], 'Renga\'da farklı şairler sırayla dize ekler; ilk dize (hokku) bağımsızlaşarak haikuya dönüşmüştür.'),
  ('Haiku\'ya bu adı veren ve onu modern biçimde yenileyen şair kimdir?', 'Masaoka Shiki', ['Yosa Buson', 'Kobayashi Issa', 'Matsuo Başo'], 'Shiki, 19. yüzyıl sonunda hokku yerine \'haiku\' terimini yaygınlaştırdı.'),
  ('Yosa Buson\'un haiku sanatında öne çıkan özelliği hangisidir?', 'Resim gibi görsel ve renkli betimlemeler', ['Ağır felsefi dil', 'Savaş temaları', 'Yalnız mistik ve doğaüstü görüntüler arayışı'], 'Buson aynı zamanda ressamdı; haikularında resimsel anlatımı öne çıkarırdı.'),
  ('Akutagawa\'nın ölümünden sonra adı verilen Akutagawa Ödülü hangi alanda verilir?', 'Yeni yazarlara edebî ödül', ['Yıllık haiku şiir yarışması', 'Tiyatro oyunu', 'Resim'], 'Ödül 1935\'te kurulmuş, Japon edebiyatının en saygın ödüllerindendir.'),
  ('Mori Ogai\'nin \'Dansçı Kız\' (Maihime) adlı hikâyesi hangi ülkedeki yaşantıyla ilişkilidir?', 'Almanya', ['Fransa', 'İngiltere', 'Rusya'], 'Ogai, Almanya\'da tıp eğitimi görmüş; hikâye Berlin\'de geçen bir aşkı anlatır.'),
  ('Kore\'nin \'Chunhyang\' öyküsü hangi sahne sanatı türünde ünlenmiştir?', 'Pansori', ['Noh', 'Kabuki', 'Peking operası'], 'Pansori, tek bir şarkıcının davul eşliğinde uzun hikâyeler anlattığı Kore halk performansıdır.'),
  ('Kore\'de Hangul ile yazılan ilk roman kabul edilen eser hangisidir?', 'Hong Gildong Jeon', ['Chunhyang Jeon', 'Samguk Yusa', 'Kuunmong'], 'Heo Gyun\'a atfedilen roman, soylu olmayan bir kahramanın adalet arayışını anlatır.'),
  ('Vietnam edebiyatının başyapıtı olarak gösterilen Nguyen Du\'nun eserinin adı nedir?', 'Kieu Öyküsü', ['Son Tang', 'Hoa Tien', 'Luc Van Tien'], 'Kieu, 3254 dizelik \'luc bat\' ölçülü bir manzumedir ve Nom yazısıyla yazılmıştır.'),
  ('Firdevsi\'den önce Şehname\'yi nazma çekmeye başlayan şair kimdir?', 'Dakiki', ['Rudeki', 'Enverî', 'Hakani'], 'Dakiki yaklaşık bin beyit yazdıktan sonra ölmüş, Firdevsi onun beyitlerini esere almıştır.'),
  ('Şehname\'de Siyavuş, ateşten geçerek hangi iftiranın aksini kanıtlar?', 'Üvey annesi Sudabe\'nin suçlamasının', ['Kralın vergi ihlalini ve Dahhak\'a yardımını', 'Rüstem\'in ihanetini', 'Kralın tahtına göz dikmesini'], 'Ateşten sağ çıkan Siyavuş masumiyetini gösterir, ancak yine de Turan\'a gidip orada öldürülür.'),
  ('Şehname\'nin çeşitli bölümlerinde farklı yüzyılları kapsayan yapı en iyi hangi bölümlendirmeyle gösterilir?', 'Mitolojik, kahramanlık ve tarihsel dönemler', ['Tragedya, komedya, dram ve satyr oyunu', 'Aşk, savaş ve yolculuk', 'Dinî, hukuki ve bilimsel'], 'Eser dünyanın yaratılışından Sasani krallarının sonuna kadar uzanır.'),
  ('Geleneğe göre Firdevsi\'nin Gazneli Mahmud\'dan beklediği altın yerine gümüş alması üzerine yaptığı karşı hamle nedir?', 'Hükümdarı hicveden bir şiir yazıp sarayı terk etmesi', ['Eseri yakması', 'Eseri başka hükümdara sunması', 'Tus\'ta ibadethaneye çekilmesi'], 'Rivayete göre sonradan pişman olan Mahmud altınları gönderir, ancak Firdevsi ölmüştür; olay efsane karakteri taşır.'),
  ('Firdevsi\'nin Şehname\'de Arapça sözcüklerden olabildiğince kaçınması hangi amacı gösterir?', 'Farsça dil ve kültürünü canlı tutma isteğini', ['Arapçayı küçümsemeyi', 'Sarayı memnun etmeyi', 'Yabancı okurları ve Arap sarayını çekmeyi'], 'Eser Yeni Farsça\'nın en saf ve güçlü örneği sayılır; İran ulusal kimliğinin temel kaynaklarından biridir.'),
  ('Şehname\'de Keykavus\'un göğe çıkmak için başvurduğu yöntem nedir?', 'Kartallara bağlı bir taht yaptırması', ['Dağa tırmanması', 'Büyülü ata binmesi', 'Dev bir merdiven kurup göğe tırmanması'], 'Kibirli kral kartallarla havalanır ama düşer; İran destanlarında gurur ve cezanın simgesidir.'),
  ('Şehname\'de Bijen ile Manije\'nin öyküsünde Bijen nereye hapsedilir?', 'Derin bir kuyuya', ['Bir kaleye', 'Bir mağaraya', 'Bir ağaç kovuğuna'], 'Bijen\'i kurtaran Rüstem, Afrasiyab\'ın kızı Manije\'nin sevgilisini kuyudan çıkarır.'),
  ('Simurg\'un gösterdiği dalla yapılan okla yenilmez sayılan İsfendiyar\'ı öldüren Şehname kahramanı kimdir?', 'Rüstem', ['Zal', 'Kave', 'Keyhüsrev'], 'Rüstem, Simurg\'un verdiği çalı dalından yapılan okla İsfendiyar\'ın gözünü vurur.'),
  ('Hakani\'nin Hacca giderken Irak\'ta gördüklerini anlattığı eser hangisidir?', 'Tuhfetü\'l-Irakeyn', ['Mantıku\'t-Tayr', 'Gülistan', 'Bostan'], 'Tuhfetü\'l-Irakeyn, Hakani\'nin Irak yolculuğunu anlatan manzum seyahat eseridir.'),
  ('Senai\'nin \'Hadikatü\'l-Hakika\' adlı mesnevisi hangi türdendir?', 'Tasavvufi ve ahlaki öğretici eser', ['Savaş destanı ve kahramanlık anlatısı', 'Aşk hikâyesi', 'Siyasi hiciv'], 'Gazneli sarayında yaşamış Senai, bu eserle tasavvufi mesnevi geleneğini başlatmış sayılır.'),
  ('Nizami Gencevi\'nin \'Heft Peyker\' (Yedi Güzel) mesnevisinin konusu hangi hükümdardır?', 'Behram Gur', ['Keykavus', 'Keyhüsrev', 'Cemşid'], 'Behram Gur\'un yedi iklimden yedi prensesle evlenmesi ve her biriyle farklı renkte bir köşkte hikâye dinlemesi anlatılır.'),
  ('Nizami Gencevi\'nin \'Mahzenü\'l-Esrar\' mesnevisi hangi türdendir?', 'Ahlaki ve tasavvufi öğretici mesnevi', ['Aşk hikâyesi', 'Tarihî destan', 'Seyahatname'], 'Hamse\'nin ilk eseri olan Mahzenü\'l-Esrar (Sırlar Hazinesi) öğretici hikâyelerle ahlak ilkelerini işler.'),
  ('Nizami\'nin Hamse\'sindeki eserlerden hangisi Büyük İskender\'e ayrılmıştır?', 'İskendername', ['Heft Peyker', 'Leyla vü Mecnun', 'Mahzenü\'l-Esrar'], 'İskendername iki bölümden oluşur; birincisi fetihleri, ikincisi iskenderin filozof ve peygamber yönünü anlatır.'),
  ('Sadi\'nin Gülistan\'ı biçim bakımından hangi özelliğiyle ayrılır?', 'Düzyazı içine şiirler serpiştirilmiş olması', ['Tamamen mesnevi olması', 'Yalnız gazellerden ve kasidelerden oluşması', 'Tamamen düzyazı olması'], 'Gülistan nesir ve nazmın karışımıyla, öğretici hikâyeler ve nükteler içerir; Bostan ise manzumdur.'),
  ('Sadi\'nin \'Âdemoğulları bir vücudun azalarıdır\' diye başlayan dizeleri hangi değeri vurgular?', 'İnsanlar arası dayanışma ve merhamet', ['Savaşın gerekliliği ve hükümdara itaat', 'Soyun üstünlüğü', 'Zenginliğin önemi'], 'Bu dizeler Gülistan\'dan alınıp evrensel insanlık ve dayanışmanın simgesi olmuştur.'),
  ('Hafız\'ın Divanı\'nın İran kültüründe fal kitabı olarak kullanılmasının nedeni nedir?', 'Gazellerinin çok katmanlı, yoruma açık ve \'gaybın dili\' sayılan bir anlatıma sahip olması', ['Kitabın büyülü sayılması', 'Bir hükümdarın buyruğu', 'Kitabın kısa olması'], 'Hafız\'a \'lisanü\'l-gayb\' (gayb dili) denir; gazellerin çok anlamlılığı niyet açma geleneğine yol açmıştır.'),
  ('Abdurrahman Cami\'nin Gülistan\'a öykünerek yazdığı düzyazı ve şiir karışımı eser hangisidir?', 'Baharistan', ['Leyla vü Mecnun', 'Bostan', 'Hamse'], 'Cami, Herat\'ta yaşamış son büyük klasik Fars şairlerinden olup Baharistan\'ı genç öğrencisi için yazmıştır.'),
  ('Cami\'nin Ali Şir Nevai ile ilişkisi nasıldı?', 'Yakın dostluk ve karşılıklı saygı', ['Düşmanlık', 'Hiç tanışmama', 'Usta-çırak olmamakla birlikte rekabet'], 'Herat\'ta yaşayan Cami ile Nevai arasında yakın dostluk vardı; Nevai ona Hamsetü\'l-Mütehayyirin\'i yazdı.'),
  ('Fars şiirinde \'kaside\' nazım biçimi genellikle hangi amaçla yazılır?', 'Övgü, çoğunlukla bir hükümdarı övmek', ['Aşk anlatmak', 'Şaraba ve şölen meclislerine methiye', 'Ağıt yakmak'], 'Kaside, Anvari ve Hakani gibi şairlerde saray övgüsü olarak kullanılır.'),
  ('Enverî hangi konuda Fars şiirinde öne çıkar?', 'Selçuklu sarayına yazdığı kasidelerde', ['Aşk mesnevilerinde', 'Seyahat anlatılarında ve mesnevilerde', 'Düzyazı denemelerinde'], 'Enverî, Selçuk hükümdarı Sencer\'in şairidir; kasidelerinde bilimsel bilgilerle süslü bir anlatım kullanır.'),
  ('Nasır-ı Hüsrev\'in \'Sefername\'si ne tür bir eserdir?', 'Yolculuk anıları', ['Aşk mesnevisi', 'Fıkra ve nükte derlemesi', 'Dil bilgisi'], 'Nasır-ı Hüsrev, Mısır\'a ve Hac\'ca yaptığı yedi yıllık yolculuğu anlatır.'),
  ('Beyhaki\'nin Tarih-i Beyhaki adlı eseri hangi sultanlar çağını anlatır?', 'Gazneli sultanlar dönemini', ['Büyük Selçuklu sultanları dönemini', 'Samani emirleri', 'Timurlular'], 'Beyhaki, düzyazıyla yazdığı eserde Gazneli saray hayatını canlı ayrıntılarla anlatır.'),
  ('Nizamülmülk\'ün Siyasetname\'sinin yazılma amacı nedir?', 'Selçuklu hükümdarına devlet yönetimi hakkında rehberlik etmek', ['Bir aşk hikâyesini anlatmak', 'Dilbilgisi öğretmek', 'Bir seyahati anlatmak'], 'Selçuklu veziri Nizamülmülk, eserinde adalet, vergi, casusluk ve ordu gibi konuları işler.'),
  ('Ömer Hayyam\'ın, Melikşah için hazırladığı ve bugünün takvimine çok yakın olan sistem hangisidir?', 'Celali takvimi', ['Hicri takvim', 'Jülyen takvimi', 'Rumi takvim'], 'Hayyam, Selçuklu sultanı Melikşah\'ın isteğiyle güneş yılına dayalı Celali takvimini düzenleyen heyette yer aldı.'),
  ('Muallakat şairlerinden Züheyr bin Ebi Sülma\'nın şiirinde baskın niteliği hangisidir?', 'Hikmetli sözler ve barış çağrısı', ['Aşk acısı', 'Ağıt', 'Alaycı hiciv ve kabile övünmesi'], 'Züheyr kabileler arası kan davasını sona erdirenleri över; şiiri öğütlerle doludur.'),
  ('Maarri\'nin Risaletü\'l-Gufran adlı eseri hangi sonraki yapıtla karşılaştırılır?', 'Dante\'nin İlahi Komedya\'sıyla', ['Don Kişot\'la', 'Faust\'la', 'Robinson Crusoe\'yla ve Gulliver\'in Gezileri\'yle'], 'Cennet ve cehennem gezisini anlatan eser, Dante\'ye öncülük edip etmediği tartışmasıyla bilinir.'),
  ('İbn Hazm\'ın \'Tavku\'l-Hamame\' adlı eseri hangi konuyu ele alır?', 'Aşkın doğası ve belirtileri', ['Savaş stratejisi ve askerî taktikler', 'Hukuk kuralları', 'Doğa bilimleri'], 'Güvercin Gerdanlığı, aşk üzerine yazılmış psikolojik bir incelemedir.'),
  ('İbn Zeydun\'un şiirlerinde adı geçen ve sevgilisi olan Endülüslü prenses kimdir?', 'Veladde', ['Muhammed bin Abbad', 'Leyla', 'Hansa'], 'Kurtuba\'da yaşayan şair, Veladde\'ye olan aşkını şiirlerine yansıtmıştır.'),
  ('Cahiz\'in en büyük eseri olan Kitabü\'l-Hayevan hangi alanın örneğidir?', 'Hayvanlar hakkında edebî ve bilimsel bilgi derlemesi', ['Seyahat anlatısı', 'Şiir antolojisi', 'Hukuk kitabı'], 'Eser, hayvanlar üzerine gözlemleri şiirler, fıkralar ve felsefi tartışmalarla birleştirir.'),
  ('Makame türünün temel özelliği hangisidir?', 'Seci denen kafiyeli düzyazıyla yazılmış, kahramanın hilelerini anlatan kısa hikâyeler', ['Uzun destanlar', 'Sahne oyunları', 'Bilimsel incelemeler'], 'Makame, Bediüzzaman Hemedani\'nin geliştirdiği ve Hariri\'nin ustalaştırdığı türdür.'),
  ('Hariri\'nin Makamat\'ında anlatıcı ve kahraman kimlerdir?', 'Haris bin Hemmam ve Ebu Zeyd es-Serûcî', ['Sinbad ve Şehrazat', 'Kays ve Leyla', 'Rüstem ve Sührab'], 'Ebu Zeyd, hileci ve belagatli bir dolandırıcıdır; her makamede başka kılıkta görünür.'),
  ('Kur\'an\'ın Arap diline ve edebiyatına en belirgin etkisi hangisidir?', 'Arapçanın standartlaşması ve dil bilimi çalışmalarının doğmasına yol açması', ['Şiirin tamamen terk edilmesi', 'Farsçanın yayılması', 'Latince etkisi'], 'Kur\'an\'ı doğru okuma ve anlama çabası dilbilgisi, sözlükbilim ve belagat çalışmalarını başlatmıştır.'),
  ('Binbir Gece\'nin çerçeve hikâyesi için kaynak sayılan Farsça eser hangisidir?', 'Hezar Efsane', ['Şehname', 'Kelile ve Dimne', 'Kabusname'], 'Hezar Efsane (Bin Masal) adlı Pehlevi eserin, Binbir Gece\'nin çekirdeğini oluşturduğu kabul edilir.'),
  ('Binbir Gece\'nin farklı katmanlarında hangi üç kültürün etkisi görülür?', 'Hint, İran ve Arap', ['Yunan, Roma ve Mısır', 'Çin, Japon ve Kore', 'Türk, Moğol ve Rus'], 'Çerçeve hikâye Hint ve İran kökenlidir; Bağdat ve Kahire dönemleri masallara Arap renkleri katmıştır.'),
  ('Binbir Gece\'de sık görülen Halife Harun Reşid\'in veziri ve celladı kimlerdir?', 'Cafer ve Mesrur', ['Sinbad ve Ali Baba', 'Dinarzat ve Şehriyar', 'Ali ve Hasan'], 'Halife, gece kılık değiştirip Bağdat sokaklarında dolaşırken yanında Cafer ve Mesrur bulunur.'),
  ('Binbir Gece\'de Şehrazat\'ın kız kardeşi olan ve masalları dinletmek için yardım eden kişi kimdir?', 'Dinarzat', ['Nahide', 'Mercane', 'Şirin'], 'Dinarzat, her sabah masalın devamını istemekle Şehrazat\'ın masala devam etmesine yardımcı olur.'),
  ('Binbir Gece\'de bir şişenin içindeki cinin balıkçıyı öldürmek istemesi hangi sonuca varır?', 'Balıkçının hile ile cini yeniden şişeye hapsetmesi', ['Cinin balıkçıya hazine verip onu zengin etmesi', 'Balıkçının cinle dost olması', 'Cinin şişeden hiç çıkamaması'], 'Cin, balıkçı onu kurtardığı halde kendisini öldürmek istediğinde balıkçı hileyle cini yeniden şişeye sokar.'),
  ('Cibran\'ın Lübnan kökenli olup Amerika\'da yaşayan şair ve yazarlarla kurduğu edebiyat topluluğu hangisidir?', 'Mehcer (Göç) Edebiyatı', ['Divan topluluğu', 'Apollo', 'Hallaç'], 'Cibran, Mihail Nuayme gibi isimlerle birlikte Arap şiirine romantik bir yenilik getirmiştir.'),
  ('Tevfik el-Hakim\'in Arap edebiyatındaki yeri nedir?', 'Modern Arap tiyatrosunun öncüsü', ['İlk Arap romancısı ve hikâyecisi', 'İlk Arap şairi', 'Hiciv şairi'], '\'Ashab-ı Kehf\' gibi oyunlarıyla Arap tiyatrosunu fikir tiyatrosu yönünde geliştirmiştir.'),
  ('Gassan Kenefani\'nin \'Güneşte Kalanlar\' romanı hangi sorunu işler?', 'Filistinli mültecilerin çaresizliğini', ['Tarım sorunlarını', 'Aile entrikalarını ve miras kavgalarını', 'Dinî kavgaları'], 'Roman, Kuveyt\'e gizlice geçmeye çalışan üç Filistinlinin ölümünü anlatır.'),
  ('Sadık Hidayet\'in \'Kör Baykuş\' romanı hangi yönüyle bilinir?', 'Karanlık, bunalımlı ve rüya benzeri anlatımıyla', ['Destansı anlatımıyla', 'Hiciv yoluyla', 'Çocuk masalı olmasıyla'], '1936\'da yayımlanan roman, modern Fars edebiyatının en etkili ve en karamsar eserlerindendir.'),
  ('Furuğ Ferruhzad hangi alanda öne çıkar?', 'Kadın bakış açısıyla yazdığı cesur modern şiir', ['Seyahat anlatısı', 'Tarihî roman', 'Tiyatro'], '1967\'de genç yaşta ölen Furuğ, cesur ve kişisel şiirleriyle modern Fars edebiyatının önemli sesidir.'),
  ('Ali Ekber Dehhoda\'nın \'Lügatname\'si neyi içerir?', 'Büyük bir Farsça sözlük ve ansiklopedi', ['Bir şiir antolojisi ve edebiyat tarihi', 'Bir tarih kitabı', 'Bir hukuk kitabı'], 'Dehhoda\'nın yarım yüzyıl süren çalışması Farsça\'nın en kapsamlı sözlüğüdür.'),
  ('Faiz Ahmed Faiz\'in şiirleri hangi tutumu yansıtır?', 'Sosyalist, hümanist ve direnişçi bir bakışı', ['Saray övgüsü', 'Mistik zühdü', 'Savaş övgüsü'], 'Pakistanlı Urdu şairi, sürgün ve hapis yıllarını şiire dönüştürmüş, geniş çevrelerde okunmuştur.'),
  ('Avesta\'nın en eski bölümleri olan ve Zerdüşt\'e atfedilen ilahilere ne ad verilir?', 'Gathalar', ['Yaştlar', 'Vendidad', 'Visperad'], 'On yedi Gatha, Avesta\'nın Yasna bölümünde yer alır ve Eski Avestaca ile yazılmıştır.'),
  ('Ardâ Virâz Nâme neyi anlatır?', 'Bir Zerdüşt rahibinin öbür dünya yolculuğunu', ['Bir hükümdarın savaşlarını ve zaferlerini', 'Bir aşk hikâyesini', 'Bir tüccarın yolculuğunu'], 'Cennet ve cehennem gezisini anlatan Pehlevi metni, bazen Dante\'nin İlahi Komedya\'sıyla karşılaştırılır.'),
  ('Pehlevi edebiyatının dili olan Orta Farsçanın dönemi hangi hanedanlara denk gelir?', 'Sasani dönemine', ['Samani dönemine', 'Gazneli dönemine', 'Selçuklu dönemine'], 'Sasani çağında yazılan Pehlevi metinleri, sonraki Arapça ve Farsça edebiyatı etkilemiştir.'),
  ('Tamil edebiyatının en ünlü ahlak eseri olan Tirukkural\'ın yazarı kimdir?', 'Tiruvalluvar', ['Kamban', 'Ilango Adigal', 'Kabir'], 'Tirukkural, 1330 ikili dizeden oluşur ve erdem, servet ve aşk üzerine üç bölümdür.'),
  ('Tirukkural\'ın üç bölümü hangi konulara ayrılmıştır?', 'Erdem, servet ve aşk', ['Savaş, barış, din', 'Doğa, tanrı, insan', 'Tarım, ticaret, hukuk'], 'Tamil geleneğinde bu bölümler aram, porul ve inbam olarak anılır.'),
  ('Silappatikaram (Halhal Destanı) hangi dilin başlıca destanıdır?', 'Tamilce', ['Sanskritçe', 'Urduca', 'Bengalce'], 'Ilango Adigal\'ın eserinde Kannagi, kocasının haksız öldürülmesine karşı Madurai\'yi yakar.'),
  ('Tayland\'ın ulusal Ramayana uyarlaması hangi adı taşır?', 'Ramakien', ['Reamker', 'Kakawin', 'Hikayat Seri Rama'], 'I. Rama döneminde derlenen Ramakien, Tayland sarayı için yeniden yazılmıştır.'),
  ('Endonezya\'da Ramayana ve Mahabharata\'yı canlandıran, deri kuklalarla gösterilen gölge oyunu türü hangisidir?', 'Wayang kulit', ['Karagöz', 'Bunraku', 'Kathakali'], 'Wayang kulit, Cava ve Bali\'de Hint destanlarını yerel renklerle sahneleyen UNESCO tarafından korunan bir gelenektir.'),
  ('Ur\'un Yıkılışı Ağıtı gibi metinler hangi dilin edebiyatına aittir?', 'Sümerce', ['Akadça', 'Hititçe', 'Aramice'], 'Sümer şehir ağıtları, kentin yıkımını tanrıların terk edişiyle ilişkilendirir.'),
  ('Talmud\'un iki ana bölümü hangisidir?', 'Mişna ve Gemara', ['Tora ve Neviim', 'Mezmur ve Atasözleri', 'Tekvin ve Çıkış'], 'Mişna sözlü yasaların derlemesi, Gemara ise bunlar üzerine tartışmalardır.'),
  ('Maimonides\'in \'Şaşkınların Rehberi\' adlı eseri hangi alanda yazılmıştır?', 'Din ve felsefe', ['Tarih', 'Şiir', 'Dilbilgisi ve söz dizimi'], 'Musa bin Meymun, akıl ile vahyi uzlaştırma çabasını bu eserde sürdürmüştür.'),
  ('İlyada ile Odysseia\'nın başlıca değer vurgusunu karşılaştıran hangi ifade doğrudur?', 'İlyada onur ve kahramanlık şöhretini, Odysseia zekâ ve eve dönüşü ön plana çıkarır', ['İlyada zekâyı, Odysseia savaş onurunu ön plana çıkarır', 'İkisi de yalnız tanrıların gücünü över', 'İkisi de aşkı tek tema yapar'], 'Akhilleus savaşta ölümsüz ün (kleos) peşindedir; Odysseus ise kurnazlığı ve sabrıyla eve dönmeyi başarır.'),
  ('Antik Yunan edebiyatı dönemleri düşünüldüğünde, tragedyanın altın çağı aşağıdakilerden hangisine denk gelir?', 'Atina\'nın Klasik Çağı (M.Ö. 5. yüzyıl)', ['Arkaik Çağ', 'Hellenistik Çağ (İskenderiye dönemi)', 'Bizans Çağı'], 'Aiskhylos, Sophokles ve Euripides Perikles dönemi Atinası\'nda eser vermişlerdir.'),
  ('Hellenistik Çağ edebiyatı Klasik Çağ\'dan hangi yönüyle ayrılır?', 'Edebiyat merkezinin İskenderiye\'ye kayması ve bilgin şairlerin öne çıkması', ['Tragedya türünün zirve yapması', 'Destanların ilk kez yazılması', 'Düzyazının kaldırılması'], 'İskenderiye\'de bilimsel çalışmalar ve süslü, özenli şiir öne çıkmıştır.'),
  ('Tragedyada oyuncuların kısa ve hızlı biçimde birer dize karşılıklı konuşmasına ne ad verilir?', 'Stikhomythia', ['Parabasis', 'Stasimon', 'Prologos'], 'Stikhomythia, çatışmanın hızlandığı, söz düellosuna benzeyen diyalog biçimidir.'),
  ('Antik tiyatroda iç mekânda geçen olayların sonucunu göstermek için sahneye çıkarılan tekerlekli platforma ne ad verilir?', 'Ekkyklema', ['Mekhane', 'Periaktos', 'Theologeion'], 'Cinayet sonrası ceset gibi iç mekân olaylarının sonucu bu araçla seyirciye gösterilirdi.'),
  ('Maecenas\'ın Roma edebiyatındaki yeri nedir?', 'Vergilius ve Horatius gibi şairleri koruyan zengin sanat hamisi', ['Roma\'nın ilk tragedya yazarı', 'Aeneis\'in çevirmeni', 'Augustus\'un düşmanı'], 'Maecenas\'ın adı sonradan \'mesen\' sözcüğüyle sanat koruyucularını anlatır.'),
  ('Latin edebiyatında \'Gümüş Çağ\' dönemini hangi yazar temsil eder?', 'Seneca ve Tacitus', ['Cicero ve Caesar', 'Vergilius ve Horatius', 'Ennius ve Plautus'], 'Gümüş Çağ, Augustus sonrası imparatorluk dönemidir ve daha retorik, kimi zaman karamsar bir anlatım taşır.'),
  ('İlyada\'da Hera, Zeus\'un dikkatini Akhaların lehine dağıtmak için hangi yola başvurur?', 'Zeus\'u uyutup kandırması', ['Zeus\'a zehir içirmesi', 'Zeus\'u Olympos\'tan kovması', 'Zeus\'un yıldırımını çalması'], 'Hera, Aphrodite\'den ödünç aldığı kuşakla Zeus\'u baştan çıkarır ve Hypnos aracılığıyla uyutur.'),
  ('İlyada\'nın yedinci bölümündeki dövüşün ardından Hektor ile Aias hangi armağanları değiş tokuş eder?', 'Kılıç ile kuşak', ['Miğfer ile kalkan', 'Yay ile ok', 'Bilezik ile yüzük'], 'Birbirlerine saygı gösteren iki düşman savaşçı, savaş geleneğindeki asil davranışı sergilemiş olur.'),
  ('İlyada\'da Odysseus ve Diomedes\'in gece casusluk görevinde yakaladıkları Truvalı casus kimdir?', 'Dolon', ['Pandaros', 'Rhesos', 'Antenor'], 'Dolon bilgi verdikten sonra öldürülür; Odysseus ile Diomedes, Rhesos\'un atlarını da ele geçirir.'),
  ('Bir kahramanın savaşta üstün başarı gösterdiği, tek başına düşmanları püskürttüğü bölümlere Homerik anlatıda ne ad verilir?', 'Aristeia', ['Nekyia', 'Katalog', 'Prooimion'], 'Diomedes\'in, Patroklos\'un ve Akhilleus\'un savaşları İlyada\'da aristeia örnekleridir.'),
  ('Odysseus\'un sal yıkıldıktan sonra boğulmaktan kurtulmasını sağlayan deniz tanrıçası kimdir?', 'Leukothea', ['Thetis', 'Amphitrite', 'Nausikaa'], 'Leukothea\'nın verdiği örtü Odysseus\'u boğulmaktan korur ve onu Phaiakya kıyısına ulaştırır.'),
  ('Odysseus İthaka\'ya vardığında neden dilenci kılığında dolaşır?', 'Taliplerin gücünü ve kimin sadık olduğunu anlamak için', ['Poseidon\'dan saklanıp denizden kaçmak için', 'Penelope\'yi sınamak için', 'Sirenleri kandırmak için'], 'Athena onu yaşlı dilenciye çevirir; böylece sarayda gözlem yapabilir ve sadıkları belirleyebilir.'),
  ('Aeneis\'te savaşçı kadın olarak yer alan Volsk prensesi kimdir?', 'Camilla', ['Lavinia', 'Dido', 'Amata'], 'Camilla hızlı koşuşu ve savaş becerisiyle öne çıkar; sonunda ölür.'),
  ('Aeneis\'te Aeneas\'ın dümencisi Palinurus\'a ne olur?', 'Uykusunda denize düşüp boğulur', ['Savaşta ölür', 'Kartaca\'da kalır ve Dido\'yla evlenir', 'İtalya\'ya ulaşır'], 'Palinurus, Uyku tanrısının hilesiyle denize düşer; Aeneas onun yokluğunda gemiyi kendisi yönetir.'),
  ('Sima Qian\'ın \'Shiji\' (Tarihçinin Kayıtları) adlı eseri Çin kültüründe hangi bakımdan temel sayılır?', 'Çin tarihyazımının ve biyografi türünün temeli olması', ['İlk Çin romanı olması', 'İlk Çin şiir derlemesi olması', 'İlk Çin sözlüğü olması'], 'Han dönemi tarihçisi Sima Qian, hanedanları ve ünlü kişileri kapsayan geniş bir tarih yazmıştır.'),
  ('Liu Xie\'nin \'Wenxin Diaolong\' adlı eseri hangi alanda yazılmıştır?', 'Edebiyat kuramı ve eleştirisi', ['Tarih yazımı', 'Tıp', 'Askerî strateji ve savaş sanatı'], 'Altı hanedan döneminde yazılan eser, Çin\'in en kapsamlı edebiyat eleştirisi kabul edilir.'),
  ('Mo Yan\'ın Nobel Edebiyat Ödülü\'nü aldığı yıl hangisidir?', '2012', ['1998', '2005', '2019'], 'Mo Yan, 2012\'de halk masalı ve tarihi hayalî gerçekçilikle birleştiren romanlarıyla Nobel aldı; \'Kızıl Darı Tarlaları\' eserlerindendir.'),
  ('\'Hyakunin Isshu\' (Yüz Şair Yüz Şiir) antolojisi aşağıdakilerden hangisinde de kullanılır?', 'Karuta kart oyununda', ['Noh maskelerinde', 'Samuray eğitiminde', 'Kabuki sahne dekorunda'], 'Fujiwara no Teika tarafından derlenen antolojinin şiirleri bu geleneksel kart oyununun içeriğidir.'),
  ('Ueda Akinari\'nin \'Ugetsu Monogatari\' (Yağmur ve Ay Öyküleri) adlı eseri hangi türde yazılmıştır?', 'Hayalet ve doğaüstü öyküler', ['Savaş destanı', 'Seyahat günlüğü ve manzum anılar', 'Komedi oyunu'], 'Edo dönemi öyküleri, Çin ve Japon kaynaklı doğaüstü anlatılara dayanır; Mizoguchi\'nin filmine kaynaklık etmiştir.'),
  ('47 Ronin\'in intikam öyküsünü işleyen ve Kabuki/Bunraku sahnelerinde en çok oynanan oyun hangisidir?', 'Chushingura', ['Sonezaki Shinju', 'Kanadehon', 'Oku no Hosomichi'], 'Efendisinin ölümünün intikamını alan 47 samurayın öyküsü, Japon sahne sanatlarında tekrar tekrar işlenmiştir.'),
  ('Heian dönemi kadın yazarlarının Çince yerine Japonca ve kana ile yazmasının sonucu nedir?', 'Japonca düzyazının ve günlük, roman türlerinin gelişmesi', ['Şiirin yok olması', 'Çinceden tamamen kopuş', 'Tiyatronun doğuşu'], 'Murasaki ve Sei Shonagon gibi yazarlar kana ile yazarak Japon edebî dilinin gelişimine büyük katkı sağladı.'),
  ('Kautilya\'ya (Chanakya) atfedilen Arthashastra neyi ele alır?', 'Devlet yönetimi, ekonomi ve dış politika', ['Aşk sanatı', 'Dil bilgisi', 'Tanrılara adak ve kurban ritüelleri'], 'Mauryalar dönemine dayandırılan eser, devletin yönetiminde pratik ve gerçekçi öğütler verir.'),
  ('Vatsyayana\'ya atfedilen Kamasutra\'nın asıl kapsamı nedir?', 'Aşk, evlilik ve ilişkilere dair toplumsal bir yaşam rehberi', ['Savaş kitabı', 'Dil bilgisi', 'Tıp ansiklopedisi'], 'Kamasutra, yalnız cinsellik değil, sevgi, ilişkiler ve görgü kurallarını da kapsayan bir Sanskrit metnidir.'),
  ('Sanskrit dilinin edebî ve dinî dil olarak yerini Hindistan\'da hangi dönemde koruduğu söylenebilir?', 'Antik ve orta çağlar boyunca ortak bilgin dili olarak', ['Yalnız Vedik dönemde', 'Yalnız Moğollar döneminde ve saray yazışmalarında', 'Yalnız modern dönemde'], 'Sanskrit; felsefe, dilbilgisi, tıp ve edebiyat dili olarak yüzyıllarca kullanılmıştır.'),
  ('Kelile ve Dimne\'nin yazılma amacı nedir?', 'Hayvan öyküleriyle hükümdarlara ve halka siyasi öğüt vermek', ['Çocuklara alfabeyi öğretmek', 'Bir savaşı anlatmak', 'Tarih kaydetmek'], 'Eser, dolaylı anlatımla (alegori) iktidar ilişkilerini ve ahlaki dersleri işler.'),
  ('Kelile ve Dimne\'nin Kanuni döneminde Ali Çelebi tarafından yapılan Türkçe düzyazı uyarlamasının adı nedir?', 'Hümayunname', ['Kabusname', 'Hadikatü\'s-Süeda', 'Harname'], 'Ali Çelebi, Anvar-ı Süheyli\'yi esas alarak Kelile ve Dimne\'yi Kanuni\'ye sunduğu Hümayunname adıyla Türkçeleştirmiştir.'),
  ('Homeros\'un Akha ordusuna kullandığı başka adlardan ikisi hangi seçenekte doğru verilmiştir?', 'Danaoslar ve Argoslular', ['Dorlar ve İonlar', 'Pelasglar ve Lelegler', 'Mirmidonlar ve Lykialılar'], 'Homeros, Yunanlıları tek bir ulus adıyla anmaz; Akhalar, Danaoslar ve Argoslular terimlerini birbirinin yerine kullanır.'),
  ('Homeros\'un Paris için kullandığı ikinci ad aşağıdakilerden hangisidir?', 'Aleksandros', ['Aineias', 'Deiphobos', 'Helenos'], 'Paris\'e Homeros metninde sıkça Aleksandros denir; Helene\'yi kaçıran Priamos oğludur.'),
  ('Gılgamış\'ın annesi olan ve destanda ona yol gösteren tanrıça kimdir?', 'Ninsun', ['İştar', 'Ereşkigal', 'Aruru'], 'Ninsun, Gılgamış\'ın tanrısal yarısının kaynağıdır ve oğlunun rüyalarını yorumlar.'),
  ('Mahabharata\'da Pandava kardeşler kaç kişidir ve hangi isimler arasında Arjuna yer alır?', 'Beş; Yudhişthira, Bhima, Arjuna, Nakula, Sahadeva', ['Üç; Rama, Lakshmana, Bharata', 'Yedi; Karna, Drona, Bhişma, Kripa, Aşvatthama, Kunti, Vyasa', 'Dört; Duryodhana, Dushasana, Karna, Shakuni'], 'Pandavalar Kunti ve Madri\'nin oğullarıdır; Draupadi ile evlenerek beşi de eş olur.'),
  ('Mahabharata\'da Gita öğretisi hangi anda verilir?', 'Savaş başlamadan hemen önce, iki ordunun karşılaştığı yerde', ['Savaş bittikten sonra, taç giyme töreninde', 'Pandavaların sürgün yıllarında', 'Draupadi\'nin evlenme töreninde'], 'Arjuna akrabalarına karşı savaşmaktan çekinir; Krişna dharma ve eylem üzerine öğüt vererek onu savaşa hazırlar.'),
  ('Hint geleneğinde Rama\'nın tanrısal kimliği nasıl yorumlanır?', 'Vişnu\'nun yeryüzündeki bir avatarı (enkarnasyonu) olarak', ['Şiva\'nın savaşçı oğlu olarak', 'Brahma\'nın yaratığı olarak', 'Indra\'nın elçisi olarak'], 'Ramayana\'da Rama bir kral oğlu olarak doğar; Hindu inancında Vişnu\'nun yedinci avatarı kabul edilir.'),
  ('Noh oyunlarında ana rolü (çoğu zaman bir hayalet veya tanrı) oynayan oyuncuya ne denir?', 'Shite', ['Waki', 'Kyogen-kata', 'Jiutai'], 'Shite maskeli başrol oyuncusudur; waki ise onun karşısında yer alan, çoğunlukla gezgin rahip rolündeki yan rol oyuncusudur.'),
  ('Cahiliye şiirinin yazıya geçmeden önceki yaşama biçimi hangi kişi grubuna dayanır?', 'Şiiri ezberleyip aktaran râvilere', ['Katiplere', 'Saray vezirlerine', 'Din görevlilerine'], 'Şairin yanında râvi (aktarıcı) bulunur; şiir ezberlenerek kuşaktan kuşağa taşınırdı.'),
];
